(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"punctuation-end-sentence":{"title":"Punctuation at End of Sentence","topic":"Punctuation","questions":[{"id":"punctuation-end-sentence-q0001","version":4,"contentHash":"sha256:486ea6d8e0b018e16091f518a8c6cf4932342b66f44a0619640720548c3e79a3","question":"Which sentence uses end punctuation that matches the meaning?","choices":["What time is rehearsal.","What time is rehearsal?","What time is rehearsal!","What time is rehearsal,"],"correct":1,"studyAid":{"definition":"Every sentence must end with punctuation. Use a question mark for interrogative sentences that ask for information.","example":"Where are my shoes? (Question), I have a red ball. (Statement), Watch out! (Exclamation)","strategyClue":"Read the sentence out loud and listen to your tone. If your voice naturally rises at the end like you are expecting an answer, you need a question mark.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: What time is rehearsal?. This sentence is an interrogative sentence, which means it is asking a direct question. All direct questions must end with a question mark.","incorrect":[{"choice":"What time is rehearsal.","category":"incorrect end punctuation","reason":"A period is used for statements, not questions. Since the sentence asks 'What time', it requires a question mark rather than a period."},"",{"choice":"What time is rehearsal!","category":"incorrect end punctuation","reason":"An exclamation point is for showing strong emotion or shouting. Because this is a simple request for information, it should not have an exclamation point."},{"choice":"What time is rehearsal,","category":"incorrect end punctuation","reason":"A comma is used to connect parts of a sentence or separate items in a list. It is never used to end a complete sentence."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":1,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0002","version":3,"contentHash":"sha256:6b951ce6769ae6ef033a256441a1828b884e555e8b684bca232265674da2bf4a","question":"Which sentence should end with a period because it is an indirect question?","choices":["Can you tell me where the office is","Where is the office","I wonder where the office is","Is the office near the gym"],"correct":2,"studyAid":{"definition":"A direct question asks for information and needs a question mark. An indirect question is a statement that tells us what someone is wondering or asking, and it ends with a period.","example":"Direct: Where is the ball? Indirect: I wonder where the ball is.","strategyClue":"Look for sentences that start by describing a person's thoughts or feelings (like 'I wonder' or 'She asked') rather than sentences that start with an interrogative word or an auxiliary verb meant to prompt a direct answer.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: I wonder where the office is. This is an indirect question because it tells us someone is wondering something rather than directly asking a question to a listener. Because it is a statement, it requires a period instead of a question mark.","incorrect":[{"choice":"Can you tell me where the office is","category":"direct question","reason":"This is a direct question because you are asking someone for information. It requires a question mark at the end."},{"choice":"Where is the office","category":"direct question","reason":"This is a direct question starting with an interrogative word. It needs a question mark because it is asking for specific information."},"",{"choice":"Is the office near the gym","category":"direct question","reason":"This is a yes-or-no question that asks the listener for a response, making it a direct question that needs a question mark."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":2,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0003","version":3,"contentHash":"sha256:0f3bf14bc5278eaeb8984d6fb7a49168ede2f4090784b6ffe2e31ddfc61b07f4","question":"Which sentence correctly uses an exclamation point for urgency?","choices":["Where did you put my shoes!","I am five years old!","Watch out for the car!","What is your name!"],"correct":2,"studyAid":{"definition":"An exclamation point (!) is used to show strong emotion, excitement, surprise, or an urgent warning. Use a period for statements and a question mark for questions.","example":"Stop! (warning), Look at that giant rainbow! (excitement), How are you? (question), I like pizza. (statement)","strategyClue":"Read each sentence aloud. Ask yourself, 'Is this sentence asking for information or giving a command?' If it is a question, look for a question mark; if it is a command or an urgent alert, look for an exclamation point.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: Watch out for the car!. Exclamation points are used to express strong feelings, excitement, or urgent warnings like 'Watch out'.","incorrect":[{"choice":"Where did you put my shoes!","category":"incorrect punctuation mark","reason":"This is a direct question asking for information. Questions require a question mark at the end, not an exclamation point."},{"choice":"I am five years old!","category":"incorrect punctuation mark","reason":"This sentence is a simple statement of fact. Statements require a period at the end unless they are shouted or very surprising."},"",{"choice":"What is your name!","category":"incorrect punctuation mark","reason":"Since this sentence asks for a person's name, it is an interrogative sentence and must end with a question mark."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":3,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0004","version":5,"contentHash":"sha256:f302c5d6e55e04a90fd4a4a82be5a07c33adbd5d5da4e7386f8ac2ba30624b87","question":"Which revision correctly punctuates a polite request?","choices":["Could you lower your voice.","Could you lower your voice?","Could you lower your voice!","Could you lower your voice,"],"correct":1,"studyAid":{"definition":"A question mark is used at the end of a sentence that asks for information or makes a request, while a period is used for statements.","example":"Can you help me? (Request), I am helping you. (Statement), Will you please sit down? (Request)","strategyClue":"Read the sentence out loud and listen to your tone. If you are asking for something or seeking an answer, look for the punctuation mark that indicates a question.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: Could you lower your voice?. This is an interrogative sentence because it is asking a question, so it must end with a question mark.","incorrect":[{"choice":"Could you lower your voice.","category":"incorrect end punctuation","reason":"Ending a sentence with a period makes it a statement, but this sentence asks someone to do something. Since it begins with 'Could you', it is a question and needs a question mark."},"",{"choice":"Could you lower your voice!","category":"incorrect end punctuation","reason":"An exclamation point is used for strong emotion or surprise. Because this is a polite request phrased as a question, a question mark is the correct mark to use."},{"choice":"Could you lower your voice,","category":"incorrect end punctuation","reason":"A comma is used to connect parts of a sentence, not to end a complete thought. Every sentence must finish with a period, question mark, or exclamation point."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"compare every choice against the full rule, not justhe first visible error","estimatedTimeSeconds":55,"reviewPriority":"high","sourceSet":"punctuation-end-sentence","sequence":4,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0005","version":3,"contentHash":"sha256:69ce41d2d975f748f832402ac59f94dcdb445f8187061a958f747ee859c00f08","question":"What punctuation should end this sentence: \"How amazing that was\"?","choices":["period","question mark","exclamation point","comma"],"correct":2,"studyAid":{"definition":"An exclamation point (!) is used at the end of sentences that show strong emotions like joy, shock, surprise, or excitement.","example":"I love this book! Look out! That is incredible!","strategyClue":"Read the sentence out loud and imagine how a character would say it. If the sentence makes you want to shout or speak with extra energy, choose the mark that shows strong feeling.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: exclamation point. An exclamation point is used to end a sentence that expresses strong emotion, excitement, or surprise, such as the amazement mentioned in the sentence.","incorrect":[{"choice":"period","category":"statement punctuation","reason":"A period is used for simple statements or commands. This sentence expresses strong feeling, so a period does not convey the correct tone."},{"choice":"question mark","category":"interrogative punctuation","reason":"A question mark is only used to ask something. Even though the sentence starts with 'How', it is expressing excitement rather than requesting information."},"",{"choice":"comma","category":"incorrect punctuation mark","reason":"A comma is used to separate parts of a sentence or list items, not to end a full sentence. It cannot be used to close this thought."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":5,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0006","version":3,"contentHash":"sha256:7a76a6836a426ca4605bd9ad0006e600d75e945c8c95d454448f09321aaa68f2","question":"Which command could correctly end with a period because it is calm?","choices":["Stop the fire","Please place your folder on the desk","Look out below","Run"],"correct":1,"studyAid":{"definition":"A period is used for calm, normal commands or polite requests. An exclamation point is used for commands that are shouting, urgent, or emotional.","example":"Please sit down. (calm) Watch out! (urgent) Hand me that book. (calm) Fire! (urgent)","strategyClue":"Read each sentence out loud. If the sentence sounds like you are shouting or warning someone of danger, use an exclamation point; if it sounds like a quiet, helpful instruction, use a period.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: Please place your folder on the desk. This is a polite request given in a calm, neutral tone. Commands that are simple requests rather than urgent alerts or exclamations are correctly finished with a period.","incorrect":[{"choice":"Stop the fire","category":"imperative exclamation","reason":"This is an urgent warning about an emergency. Urgent commands or exclamations should end with an exclamation point to show strong emotion or force."},"",{"choice":"Look out below","category":"warning exclamation","reason":"This phrase is an alert to danger. Warnings are meant to grab attention quickly, so they use an exclamation point instead of a calm period."},{"choice":"Run","category":"forceful imperative","reason":"A single word command like this is usually spoken with intensity or urgency. It is rarely a calm instruction and requires an exclamation point to show its forceful nature."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":6,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0007","version":3,"contentHash":"sha256:dfabec9c9a7e34fd9e27db829a2a4540cbf57c5c3804f379289161c5a1e94a0a","question":"Which sentence has incorrect end punctuation?","choices":["Are you coming with us?","I think we should leave now.","What a beautiful day.","The meeting starts at noon."],"correct":2,"studyAid":{"definition":"Sentences end in different ways based on their purpose: periods for statements, question marks for questions, and exclamation points for excitement or strong feelings.","example":"Statement: The dog is brown. Question: Is the dog brown? Exclamation: Look at that brown dog!","strategyClue":"Read the sentence out loud to check the tone. If you are asking something, use a question mark; if you are yelling or very excited, use an exclamation point; otherwise, use a period.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: What a beautiful day. This sentence is an exclamation and should end with an exclamation point (!) instead of a period because it expresses strong emotion.","incorrect":[{"choice":"Are you coming with us?","category":"interrogative sentence punctuation","reason":"This is a direct question asking for information, so the question mark is the correct punctuation to use."},{"choice":"I think we should leave now.","category":"declarative sentence punctuation","reason":"This is a simple statement of fact or opinion, so a period is the correct way to end the sentence."},"",{"choice":"The meeting starts at noon.","category":"declarative sentence punctuation","reason":"This sentence states a time for an event, making it a declarative sentence that requires a period."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-end-sentence","sequence":7,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0008","version":4,"contentHash":"sha256:5ed9b92564342f0a8454783bb939239f2fc8b5aa99e764c8666b97b5ea785357","question":"Choose the punctuation that best fits the urgent sentence: \"Stop right there\"","choices":[".","?","!",","],"correct":2,"studyAid":{"definition":"An exclamation point (!) is used at the end of a sentence to express strong feelings, excitement, or a sudden, urgent command.","example":"Watch out! That was amazing! Stop right there!","strategyClue":"Read the sentence out loud and imagine you are shouting it at someone. If the sentence demands immediate attention or shows big emotion, choose the mark that signals that intensity.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: !. An exclamation point is used to show strong emotion, surprise, or an urgent command like 'Stop right there!'","incorrect":[{"choice":".","category":"period for statements","reason":"A period is used for regular statements or declarations. Since the sentence is an urgent command, a period is too quiet and doesn't capture the intensity needed."},{"choice":"?","category":"question mark usage","reason":"A question mark is used to show a request for information. 'Stop right there' is a command, not a question, so it should not end with a question mark."},"",{"choice":",","category":"comma misuse","reason":"A comma is used to connect parts of a sentence or create a pause, but it cannot end a complete sentence. You always need a terminal punctuation mark to finish the thought."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":8,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0009","version":4,"contentHash":"sha256:1688dedfe1f329d5015ea41a52be6c74f2fb55d2c2dba2f3701c498cd6691c68","question":"Which sentence is a statement with correct punctuation?","choices":["My favorite color is blue!","My favorite color is blue.","My favorite color is blue?","My favorite color is blue,"],"correct":1,"studyAid":{"definition":"A statement (declarative sentence) tells the reader something and must end with a period to show the thought is complete.","example":"Correct: I have a dog. / Incorrect: I have a dog! (unless very excited) / Correct: The sun is hot. / Incorrect: The sun is hot?","strategyClue":"Ask yourself if the sentence is asking for an answer or expressing excitement. If the sentence is simply sharing a fact, look for the punctuation mark that signals a full stop.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: My favorite color is blue. This sentence is a statement that shares information, so it requires a period at the end.","incorrect":[{"choice":"My favorite color is blue!","category":"exclamation point error","reason":"This uses an exclamation point, which is for strong feelings or excitement. Since this sentence is just a calm statement of fact, it needs a period instead."},"",{"choice":"My favorite color is blue?","category":"question mark error","reason":"A question mark is only used when you are asking someone for information. Because this is telling information, not asking for it, a question mark is incorrect."},{"choice":"My favorite color is blue,","category":"comma usage error","reason":"A comma indicates a pause within a sentence, not the end of a thought. Sentences that provide information must end with a period."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":9,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0010","version":3,"contentHash":"sha256:b6495ce3f3c139514099197cd5aa12d288a5d70da74fdda5ca3d06426d895246","question":"Which sentence uses correct punctuation for a tag question?","choices":["You're coming, aren't you.","You're coming, aren't you?","You're coming, aren't you!","You're coming aren't you?"],"correct":1,"studyAid":{"definition":"A tag question is a short question added to the end of a sentence to turn it into a question. You must always use a comma before the tag and a question mark at the very end.","example":"Correct: It is cold, isn't it? Incorrect: It is cold isn't it? Incorrect: It is cold, isn't it.","strategyClue":"Check for two things: First, look for a comma between the main statement and the tag. Second, check that the sentence ends with a question mark rather than a period or exclamation point.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: You're coming, aren't you?. A tag question at the end of a sentence functions as a question, so it must end with a question mark. Additionally, it requires a comma to separate the main statement from the tag.","incorrect":[{"choice":"You're coming, aren't you.","category":"incorrect ending punctuation","reason":"Because this sentence asks a question at the end, it needs a question mark, not a period."},"",{"choice":"You're coming, aren't you!","category":"incorrect ending punctuation","reason":"An exclamation mark is used for strong emotion, but since the sentence is seeking information, it requires a question mark."},{"choice":"You're coming aren't you?","category":"missing comma","reason":"You must place a comma before the tag to separate the original statement from the short question added to the end."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":10,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0011","version":3,"contentHash":"sha256:744544ed1dd8d0b73883485420f3eec47355126cc454548a6b6296048a81a56b","question":"What is wrong with this sentence: \"I wonder if it will rain today\"","choices":["Nothing","It needs a question mark","It needs a period at the end","It needs a comma"],"correct":2,"studyAid":{"definition":"A declarative sentence makes a statement or expresses an opinion and must end with a period.","example":"I like pizza. (Correct) vs. I like pizza (Incorrect). It is sunny outside. (Correct) vs. It is sunny outside! (May be too excited).","strategyClue":"Read the sentence out loud and ask yourself: 'Am I asking for information, or am I stating a fact?' If you aren't waiting for an answer, use a period.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: It needs a period at the end. This is a declarative sentence that states a thought, so it requires a period to mark the end of the statement.","incorrect":[{"choice":"Nothing","category":"missing punctuation","reason":"Every complete sentence must end with a punctuation mark. Leaving it off makes the writing look unfinished."},{"choice":"It needs a question mark","category":"incorrect punctuation mark","reason":"Even though the sentence starts with 'I wonder,' it is a statement about a feeling, not a direct question. A question mark is only used when asking for information."},"",{"choice":"It needs a comma","category":"misplaced punctuation","reason":"Commas are used to separate parts of a sentence or list items; they cannot act as a replacement for end-of-sentence marks like periods."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":11,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0012","version":3,"contentHash":"sha256:c93c5ecec113c3ad1436697b1f7c7457aed3650a96556b374e16567e2445f85c","question":"Which sentence is an exclamation, not a question?","choices":["What time does the movie start?","I love this movie.","What an exciting movie!","Do you like this movie?"],"correct":2,"studyAid":{"definition":"An exclamation is a sentence that shows strong emotion and always ends with an exclamation point (!).","example":"Wow! That is fast. / What a beautiful day! / I am so happy!","strategyClue":"Look at the end punctuation of each sentence. Exclamations use an exclamation point, while questions must use a question mark.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: What an exciting movie!. This sentence expresses strong emotion and ends with an exclamation point, making it an exclamation.","incorrect":[{"choice":"What time does the movie start?","category":"interrogative sentence","reason":"This sentence asks for information about a time and ends with a question mark, so it is a question, not an exclamation."},{"choice":"I love this movie.","category":"declarative sentence","reason":"This sentence is a statement of fact or opinion that ends with a period. It is a declarative sentence, not an exclamation."},"",{"choice":"Do you like this movie?","category":"interrogative sentence","reason":"This sentence asks someone for their opinion and uses a question mark. It is a question, not an exclamation."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-end-sentence","sequence":12,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0013","version":3,"contentHash":"sha256:5bc39a5e3f3eaa876c73985d5cf029cb3779cf0c8f7acc46a682fc4a9317bca5","question":"Which sentence has incorrect end punctuation?","choices":["Where are my keys?","I found my keys!","I found my keys?","Give me my keys."],"correct":2,"studyAid":{"definition":"Every sentence must end with the correct punctuation mark based on its purpose: statements use periods, questions use question marks, and commands or exclamations use periods or exclamation points.","example":"I like cats. (Statement) / Do you like cats? (Question) / Stop running! (Command)","strategyClue":"Read the sentence out loud and listen to the tone. Decide if the sentence is asking for information, telling a fact, or showing strong emotion, then match the end mark to that job.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: I found my keys?. A declarative sentence—one that makes a statement—requires a period (.) at the end, not a question mark (?).","incorrect":[{"choice":"Where are my keys?","category":"correct punctuation","reason":"This is a question, so it correctly ends with a question mark. It is not an error."},{"choice":"I found my keys!","category":"correct punctuation","reason":"This is an exclamation, so it correctly ends with an exclamation point. It is not an error."},"",{"choice":"Give me my keys.","category":"correct punctuation","reason":"This is a command, so it correctly ends with a period. It is not an error."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-end-sentence","sequence":13,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0014","version":3,"contentHash":"sha256:7ebd632952e6792765f14db36d53cc51a3b436d94ee761d13aa502ff174b59d8","question":"Which ending is correct for a direct question: \"Could you please pass the salt\"","choices":["!","?",".","..."],"correct":1,"studyAid":{"definition":"A question mark (?) is placed at the end of a sentence that asks a question, while a period (.) ends a sentence that makes a statement.","example":"Where is my hat? (question); I have a hat. (statement); Can you help me? (question)","strategyClue":"Ask yourself if the sentence is trying to get an answer from someone else. If you are waiting for a reply, you need a specific punctuation mark for questions.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: ?. A direct question is an inquiry that asks for information, so it must end with a question mark.","incorrect":[{"choice":"!","category":"exclamation mark usage","reason":"An exclamation mark is used for strong feelings or excitement. Since the sentence asks for information, it does not fit here."},"",{"choice":".","category":"period usage","reason":"A period is used for statements or commands. This sentence uses 'Could you,' which indicates you are asking for something, not making a statement."},{"choice":"...","category":"ellipsis usage","reason":"An ellipsis is used to show a pause or missing words. It is not a standard way to end a direct question."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":14,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0015","version":3,"contentHash":"sha256:88880e101489283573dbedc2f0877594554761d764292e33657319a00d2751e6","question":"Which sentence changes meaning if the punctuation changes from . to ?","choices":["The train leaves at six","Where the train leaves","Leaves at six","The six trains"],"correct":0,"studyAid":{"definition":"A statement provides information and ends with a period, while a question asks for information and ends with a question mark.","example":"He is going home. (Statement) vs. He is going home? (Question asking for clarification)","strategyClue":"Turn each option into a question by raising your voice at the end and adding a question mark; choose the one that becomes a clear, logical inquiry about the action described.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: The train leaves at six. Adding a question mark turns this statement into a request for information (The train leaves at six?), whereas the other choices are fragments or phrases that do not form complete, meaningful sentences in both punctuation forms.","incorrect":["",{"choice":"Where the train leaves","category":"sentence fragment","reason":"This is a dependent clause and does not act as a complete sentence regardless of the punctuation used at the end."},{"choice":"Leaves at six","category":"missing subject","reason":"This phrase lacks a subject to tell us who or what is leaving, making it an incomplete thought even with a question mark."},{"choice":"The six trains","category":"noun phrase","reason":"This is just a label for a group of trains and does not express an action or a question, so changing the punctuation does not create a functional sentence."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":15,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0016","version":3,"contentHash":"sha256:fa8b9d55eaa415c10d9518d695f24ad0fb1ef95c9ad9ceb260bd75f793ddb69a","question":"Which of the following sentences would need a question mark as its end punctuation?","choices":["Let me do the errand","Will you all pass in your homework","The class seems unprepared","Close the door behind you"],"correct":1,"explanation":{"correct":"Answer: Will you all pass in your homework. This sentence is an interrogative sentence because it asks someone to provide information or perform an action, requiring a question mark.","incorrect":[{"choice":"Let me do the errand","category":"imperative sentence","reason":"This is a request or command. Commands do not ask for information, so they typically end with a period."},"",{"choice":"The class seems unprepared","category":"declarative sentence","reason":"This sentence makes a statement of fact or opinion. Statements require a period, not a question mark."},{"choice":"Close the door behind you","category":"imperative sentence","reason":"This sentence is giving an instruction or command. Because it is telling someone what to do rather than asking a question, it needs a period."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":16,"sourceFile":"Basic-3_grammer and usage.pdf","sourceQuestionNumber":3,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A question mark is used at the end of an interrogative sentence, which is a sentence that asks for information.","example":"Where are you going? (Question) I am going home. (Statement) Go home now. (Command)","strategyClue":"Turn each sentence into a response; if the sentence sounds like it is looking for an answer rather than stating a fact or giving an order, it is an interrogative sentence.","link":"","linkText":""}},{"id":"punctuation-end-sentence-q0017","version":3,"contentHash":"sha256:0acaea92d6e936dd5963c055ade80d097d55b528040ec0962e794dd86454a025","question":"Which sentence needs a period at the end?","choices":["Why are you happy","What is your favorite color","We like to go to school","Where did you go yesterday"],"correct":2,"explanation":{"correct":"Answer: We like to go to school. This sentence is a statement, also called a declarative sentence, which must always end with a period.","incorrect":[{"choice":"Why are you happy","category":"interrogative punctuation error","reason":"This is a direct question asking for information, so it requires a question mark at the end instead of a period."},{"choice":"What is your favorite color","category":"interrogative punctuation error","reason":"Because this sentence begins with a 'what' question word and asks for a response, it must end with a question mark."},"",{"choice":"Where did you go yesterday","category":"interrogative punctuation error","reason":"Any sentence that asks a question requires a question mark at the end to correctly signal that it is an inquiry."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":17,"sourceFile":"Basic-1_Mechanics and Punctuation.pdf","sourceQuestionNumber":10,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A statement that tells information ends with a period, while a question that asks for information ends with a question mark.","example":"I like pizza. (Statement) Do you like pizza? (Question) She runs fast. (Statement) Who runs fast? (Question)","strategyClue":"Read each sentence out loud; if your voice rises at the end like you are asking someone for an answer, use a question mark. If your voice stays flat and you are simply stating a fact, use a period.","link":"","linkText":""}},{"id":"punctuation-end-sentence-q0018","version":4,"contentHash":"sha256:73998def8c9381ac3aeece06b7e6be6fe91dcd380dd626024b0c52bf884ffa42","question":"Which has the correct end mark?","choices":["Do you like to read","Do you like to read?","Do you like to read.","Do you like to read,"],"correct":1,"explanation":{"correct":"Answer: Do you like to read?. This is an interrogative sentence, or a question, so it requires a question mark at the end.","incorrect":[{"choice":"Do you like to read","category":"missing end mark","reason":"Every sentence must have an end mark to signal where the thought stops. Without one, the sentence feels incomplete."},"",{"choice":"Do you like to read.","category":"incorrect punctuation mark","reason":"A period is used for statements, but since this sentence asks something, it needs a question mark instead."},{"choice":"Do you like to read,","category":"incorrect comma usage","reason":"Commas are used to separate parts of a sentence or list items, not to end a complete thought. Use a question mark for questions."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":18,"sourceFile":"Basic-2_Mechanics and Punctuation.pdf","sourceQuestionNumber":4,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A question mark (?) is placed at the end of a sentence that asks a question to seek information.","example":"Where are you going? Do you have a pencil? Is it raining outside?","strategyClue":"Read the sentence out loud and listen to your voice. If your voice goes up at the end as if you are waiting for an answer, you need a question mark.","link":"","linkText":""}},{"id":"punctuation-end-sentence-q0019","version":4,"contentHash":"sha256:a6d193cf0f26dc49db48feb63e02b2cb476bf5372b0e0d7be944e22d2b314b98","question":"Which one has the correct mark?","choices":["Get in line for lunch","Get in line for lunch,","Get in line for lunch.","Get in line for lunch?"],"correct":2,"explanation":{"correct":"Answer: Get in line for lunch. This is a command or instruction, which is an imperative sentence, so it requires a period at the end.","incorrect":[{"choice":"Get in line for lunch","reason":"\"Get in line for lunch\" does not use the period needed for a statement, command, or indirect question."},{"choice":"Get in line for lunch,","category":"incorrect end punctuation","reason":"A comma is used to separate parts of a sentence, not to end one. Always use a period to show that an instruction has finished."},"",{"choice":"Get in line for lunch?","category":"incorrect end punctuation","reason":"A question mark is only used when asking for information. Since this sentence tells someone what to do, it is not a question."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":19,"sourceFile":"Basic-3_Mechanics and Punctuation.pdf","sourceQuestionNumber":4,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Sentences that give orders or instructions are called imperative sentences and should end with a period.","example":"Clean your room. Please pass the salt. Wash your hands before dinner.","strategyClue":"Ask yourself if the speaker is waiting for an answer or if they are telling someone to perform an action. If it is an action, choose the period.","link":"","linkText":""}},{"id":"punctuation-end-sentence-q0020","version":3,"contentHash":"sha256:8fc3e225727b19fda56377de4c42df9aa38c33ad23a712aa24cebd0d8c6f4a98","question":"Which of the following is correct?","choices":["w here did you go?","What time is dinner.","who wants a rootbeer float?","When did you read that book?"],"correct":3,"explanation":{"correct":"Answer: When did you read that book?. A complete sentence must start with a capital letter and end with a proper punctuation mark, such as a question mark for an interrogative sentence.","incorrect":[{"choice":"w here did you go?","category":"capitalization error","reason":"Every sentence must begin with a capital letter. The letter 'w' at the beginning should be capitalized as 'W'."},{"choice":"What time is dinner.","category":"incorrect end punctuation","reason":"This sentence asks a question, so it requires a question mark (?) at the end instead of a period (.)."},{"choice":"who wants a rootbeer float?","category":"capitalization error","reason":"The word 'who' is the first word in the sentence and must be capitalized to start the sentence correctly."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":20,"sourceFile":"Basic-3_Mechanics and Punctuation.pdf","sourceQuestionNumber":8,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Every sentence must begin with a capital letter and end with an appropriate punctuation mark, such as a period, question mark, or exclamation point.","example":"Where is my hat? (Correct) vs. where is my hat? (Incorrect); How are you. (Incorrect) vs. How are you? (Correct)","strategyClue":"Check every option for two things: Is the very first letter capitalized, and does the ending mark match the purpose of the sentence?","link":"","linkText":""}},{"id":"punctuation-end-sentence-q0021","version":3,"contentHash":"sha256:ba5cb6a13489abc89add483bb72a9292bcb33f993cb4a8c5e716c8722d0d862f","question":"Which sentence asks a question?","choices":["Do you want to go to the zoo","We picked apples from the apple tree","I like to walk to the pond","She went to the library"],"correct":0,"explanation":{"correct":"Answer: Do you want to go to the zoo. This sentence is an interrogative sentence because it asks for information and typically begins with an auxiliary verb like 'Do'.","incorrect":["",{"choice":"We picked apples from the apple tree","category":"declarative sentence","reason":"This is a statement of fact or action, not a question. It ends with a period because it tells us what someone did."},{"choice":"I like to walk to the pond","category":"declarative sentence","reason":"This sentence expresses a preference or opinion. Since it is telling information rather than requesting it, it is not a question."},{"choice":"She went to the library","category":"declarative sentence","reason":"This sentence provides information about where someone went. Because it makes a statement, it cannot be a question."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":21,"sourceFile":"Basic-4_Mechanics and Punctuation.pdf","sourceQuestionNumber":5,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"An interrogative sentence asks a question and usually begins with a helping verb (like 'do', 'can', or 'is') or a question word (like 'who', 'what', or 'where').","example":"Statement: You like pizza. Question: Do you like pizza? Statement: She is happy. Question: Is she happy?","strategyClue":"Read each sentence out loud and imagine you are talking to a friend; identify which sentence expects a verbal response from the listener.","link":"","linkText":""}},{"id":"punctuation-end-sentence-q0022","version":4,"contentHash":"sha256:82ce0308cf64a8ddc4f667e5b67d935b1425a47e75c4a107397fd23b1d512ea9","question":"Which punctuation is needed for the sentence below? Do you know the name of the governor of the state ___","choices":[";","!","?","."],"correct":2,"explanation":{"correct":"Answer: ?. This sentence is an interrogative sentence, which means it is asking a direct question. All direct questions must end with a question mark.","incorrect":[{"choice":";","category":"incorrect punctuation mark","reason":"A semicolon is used to link two closely related independent clauses. It is not used to end a sentence that asks for information."},{"choice":"!","category":"incorrect punctuation mark","reason":"An exclamation point is used for strong feelings or commands. Since this sentence is asking for information rather than shouting or expressing excitement, an exclamation point is incorrect."},"",{"choice":".","category":"incorrect punctuation mark","reason":"A period is used for statements or commands. Because this sentence begins with 'Do you know', it is requesting an answer and requires a question mark instead."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":22,"sourceFile":"Proficient-4_Mechanics and Punctuation.pdf","sourceQuestionNumber":8,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A question mark is used at the end of a sentence that asks for information or requests an answer.","example":"Where is the library? (Question) vs. The library is here. (Statement)","strategyClue":"Look at the first word of the sentence. If the sentence begins with words like 'Do', 'Does', 'Can', 'Who', or 'Where', ask yourself if you are expecting someone to answer you back.","link":"","linkText":""}},{"id":"punctuation-end-sentence-q0023","version":3,"contentHash":"sha256:a542fdf2b58d7d753e9b0960de9165cf338b24e38a4f95a81be7176f57ca6c25","question":"How would you end this sentence?","choices":["The house is on fire.","The house is on fire?","The house is on fire","The house is on fire!"],"correct":3,"explanation":{"correct":"Answer: The house is on fire! An exclamation point is used to show strong emotion, surprise, or urgency. Since a house being on fire is an emergency, it requires an exclamation point.","incorrect":[{"choice":"The house is on fire.","category":"incorrect punctuation mark","reason":"A period is used for statements, but this sentence expresses a strong sense of danger or alarm, which calls for a more expressive mark."},{"choice":"The house is on fire?","category":"incorrect punctuation mark","reason":"A question mark is used to ask something. Since this is an urgent announcement and not a request for information, the question mark is incorrect."},{"choice":"The house is on fire","category":"missing end punctuation","reason":"Every complete sentence must end with a punctuation mark. Leaving it off makes the sentence feel incomplete and ungrammatical."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":23,"sourceFile":"Basic-4_Mechanics and Punctuation.pdf","sourceQuestionNumber":4,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"An exclamation point (!) is used at the end of a sentence to express excitement, surprise, or strong emotion.","example":"Watch out! I am so happy! What a great surprise!","strategyClue":"Read the sentence out loud and imagine how you would say it if it were actually happening. If you would say it with a loud, urgent, or excited voice, choose the exclamation point.","link":"","linkText":""}},{"id":"punctuation-end-sentence-q0024","version":3,"contentHash":"sha256:1ecd7b56356038d3e9380de440d325d654ee844770750bc13934b5853d49a741","question":"Which of the following is an interrogative sentence?","choices":["When will your family be going on vacation","When Jerry calls please come get me","When you finish your math, you can watch TV","When the cookies are done, bring one to Mary"],"correct":0,"explanation":{"correct":"Answer: When will your family be going on vacation? An interrogative sentence is a question that asks for information and usually ends with a question mark.","incorrect":["",{"choice":"When Jerry calls please come get me","category":"imperative sentence","reason":"This is a command, not a question. You are telling someone to 'come get me' rather than asking for information."},{"choice":"When you finish your math, you can watch TV","category":"declarative sentence","reason":"This sentence makes a statement about what you are allowed to do. It does not ask a question."},{"choice":"When the cookies are done, bring one to Mary","category":"imperative sentence","reason":"This is a request or a command to 'bring one to Mary.' It is not asking a question."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":24,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":36,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"An interrogative sentence asks a question and ends with a question mark. It often starts with words like who, what, where, when, why, or how.","example":"Where is my book? When does the bell ring? Why are you late?","strategyClue":"Look at the end of the sentence to see if it asks for information or gives a command/statement. Ask yourself: 'Does this sentence demand an answer from someone?'","link":"","linkText":""}},{"id":"punctuation-end-sentence-q0025","version":3,"contentHash":"sha256:416db3d649fad7e95ce8421db794f16e26030caf3284f4b715e0496b445ebb64","question":"Which sentence asks a question?","choices":["Put the mop away","We used a mop for the floor","The mop fell on the floor","Who has the mop"],"correct":3,"explanation":{"correct":"Answer: Who has the mop. This sentence begins with an interrogative pronoun ('Who') and seeks information, making it an interrogative sentence that requires a question mark.","incorrect":[{"choice":"Put the mop away","category":"imperative sentence","reason":"This is a command or request, not a question. It tells someone to do something rather than asking for information."},{"choice":"We used a mop for the floor","category":"declarative sentence","reason":"This is a statement of fact. It tells the reader what happened instead of asking for details about the event."},{"choice":"The mop fell on the floor","category":"declarative sentence","reason":"This sentence describes an action that took place. It provides information to the reader rather than prompting a response."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":25,"sourceFile":"Basic-6_Writing strategies_Application_Style.pdf","sourceQuestionNumber":3,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"An interrogative sentence asks a question to get information and always ends with a question mark.","example":"Statement: The cat is hungry. Question: Is the cat hungry? Statement: You like pizza. Question: Do you like pizza?","strategyClue":"Look at the first word of each sentence and ask yourself, 'If someone said this to me, would I need to give an answer?'","link":"","linkText":""}},{"id":"punctuation-end-sentence-q0026","version":3,"contentHash":"sha256:8992747a4091b1285db7ed2db2942f19f06f781adb645af2145709577077edf2","question":"Which sentence is not punctuated correctly?","choices":["I at e in a restaurant last night.","I have a dog with white spots?","I love this game!","Were you tardy again?"],"correct":1,"explanation":{"correct":"Answer: I have a dog with white spots?. This sentence makes a statement, not a request for information. It should end with a period, not a question mark.","incorrect":[{"choice":"I at e in a restaurant last night.","category":"correct punctuation usage","reason":"This sentence ends with a period because it is a statement of fact. It is punctuated correctly."},"",{"choice":"I love this game!","category":"correct punctuation usage","reason":"This sentence expresses strong emotion or excitement, so an exclamation point is the correct mark to use."},{"choice":"Were you tardy again?","category":"correct punctuation usage","reason":"This sentence is a direct question asking for information, so it correctly uses a question mark at the end."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":26,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":29,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Sentences end with a period for statements, a question mark for questions, or an exclamation point for strong feelings.","example":"I like cake. (Statement) / Do you like cake? (Question) / I love cake! (Exclamation)","strategyClue":"Read the sentence out loud and decide if you are telling a fact, asking for information, or shouting with emotion before looking at the punctuation mark at the end.","link":"","linkText":""}},{"id":"punctuation-end-sentence-q0027","version":3,"contentHash":"sha256:0ff246ae9f963dbcf9a8747d856df519f9217398b2f5f4adc64b25f199ab8ef4","question":"Which of the following is an interrogative sentence?","choices":["When will your family be going on vacation","When Jerry calls please come get me","When you finish your math, you can watch TV","When the cookies are done, bring one to Mary"],"correct":0,"explanation":{"correct":"Answer: When will your family be going on vacation? An interrogative sentence is a question that asks for information and usually requires a question mark at the end.","incorrect":["",{"choice":"When Jerry calls please come get me","category":"imperative sentence","reason":"This is a command, not a question. It is giving an instruction rather than asking for information."},{"choice":"When you finish your math, you can watch TV","category":"declarative sentence","reason":"This sentence makes a statement about a future possibility. It is not asking a question."},{"choice":"When the cookies are done, bring one to Mary","category":"imperative sentence","reason":"This sentence gives a direct order or request to 'bring one to Mary.' It is not an interrogative sentence."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sequence":27,"sourceFile":"Proficient-2_Writing strategies_Application_Style.pdf","sourceQuestionNumber":10,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"An interrogative sentence asks a direct question and typically ends with a question mark.","example":"Where are my shoes? (Interrogative) vs. Put on your shoes. (Imperative)","strategyClue":"Look at each sentence and ask yourself: 'Does this sentence demand an answer, or does it give an order or a statement?' Only the choice that seeks information is interrogative.","link":"","linkText":""}},{"id":"punctuation-end-sentence-q0028","version":3,"contentHash":"sha256:8525f3c35735a83c8ce8c3084834448e9d268f8f5afd125f2ff45dc80ec5eced","question":"Use this context for sentence 1, 2, and 3: Kyle was furious that Katherine spilt Dr. Pepper all over his new white sweatshirt. (1) Sheesh (2) How did Katherine expect him to react (3) Choose the appropriate end punctuation for sentence 1.","choices":[".","!","?","*"],"correct":0,"explanation":{"correct":"Answer: .. 'Sheesh' is used here as an interjection that functions as a complete sentence or thought, and a period correctly marks the end of this declarative expression of frustration.","incorrect":["",{"choice":"!","category":"excessive emotional punctuation","reason":"While 'Sheesh' can express strong feelings, using an exclamation point here would be redundant because the rest of the paragraph already establishes Kyle's extreme anger. A period provides a more controlled, professional finish to the sentence."},{"choice":"?","category":"incorrect sentence type","reason":"A question mark is only used for sentences that ask for information. Since 'Sheesh' is an expression of feeling rather than a question, a question mark is not appropriate."},{"choice":"*","category":"invalid punctuation mark","reason":"An asterisk is used to mark a footnote or a reference, not to end a sentence. It does not indicate the end of a thought in standard English."}]},"studyAid":{"definition":"A period is used at the end of a declarative sentence, which is a sentence that makes a statement or expresses a thought.","example":"The dog barked. Sheesh. I am tired.","strategyClue":"Read the word out loud. If it is not asking a question or showing intense surprise, choose the punctuation mark that signals the end of a calm, complete statement.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"passage-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Advanced Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":4,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":28,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0029","version":4,"contentHash":"sha256:22602730a1d6bd6e014106f8c6c09abf531c530659f415f05e86699e537eb819","question":"Use this context for sentence 1, 2, and 3: Kyle was furious that Katherine spilt Dr. Pepper all over his new white sweatshirt. (1) Sheesh (2) How did Katherine expect him to react (3) Choose the appropriate end punctuation for sentence 2.","choices":["!","?",",","."],"correct":0,"explanation":{"correct":"Answer: !. This sentence expresses strong emotion and frustration, which requires an exclamation point. Even though the sentence begins with 'How did,' it functions as an exclamatory rhetorical statement of his anger rather than a question seeking information.","incorrect":["",{"choice":"?","category":"incorrect sentence type","reason":"While 'How' often starts a question, in this context, the character is expressing shock and fury. A question mark would suggest he is truly asking for information, but here he is reacting to a frustrating event."},{"choice":",","category":"punctuation error","reason":"A comma is used to connect parts of a sentence or create a pause, but it cannot end a complete sentence. Sentences must always end with a terminal mark like a period, question mark, or exclamation point."},{"choice":".","category":"insufficient emotion","reason":"A period marks a normal statement, but this situation involves extreme emotion. Using a period ignores the 'furious' context and the tone of the reaction."}]},"studyAid":{"definition":"End punctuation tells the reader how to feel or read a sentence. Use a period for statements, a question mark for inquiries, and an exclamation point for strong feelings like surprise, fear, or anger.","example":"He is happy. (statement) Is he happy? (question) He is so happy! (strong emotion)","strategyClue":"Read the sentence out loud and pay attention to the intensity of the character's feelings. If the sentence captures a moment of intense frustration or shock, choose the punctuation mark that matches that energy.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"passage-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Advanced Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":29,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0030","version":4,"contentHash":"sha256:68144cefe9f311a64865663c0a7e942d0ddf0be265b14a9ec2c3e67cb5d8f05a","question":"Use this context for sentence 1, 2, and 3: Kyle was furious that Katherine spilt Dr. Pepper all over his new white sweatshirt. (1) Sheesh (2) How did Katherine expect him to react (3) Choose the appropriate end punctuation for sentence 3.","choices":[".","?",":","!"],"correct":1,"explanation":{"correct":"Answer: ?. This sentence is a direct question asking for information about Katherine's expectations, so it requires a question mark.","incorrect":[{"choice":".","category":"incorrect sentence type","reason":"A period is used for statements, but this sentence asks 'How did Katherine expect him to react', which is a question."},"",{"choice":":","category":"incorrect punctuation mark","reason":"A colon is used to introduce a list or an explanation, not to end a question. Use a question mark to show the reader you are asking for an answer."},{"choice":"!","category":"misplaced exclamation point","reason":"An exclamation point shows strong emotion or surprise. While Kyle is furious, the sentence structure clearly asks a question, making a question mark the best choice."}]},"studyAid":{"definition":"A question mark is used at the end of a sentence that asks for information, while a period ends a statement and an exclamation point expresses strong emotion.","example":"Where are you going? (question) I am going home. (statement) What a surprise! (exclamation)","strategyClue":"Turn the sentence into a statement to see if it makes sense. If you are waiting for an answer from the listener, the sentence is a question and needs a specific punctuation mark at the end.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"passage-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Advanced Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":6,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":30,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0031","version":3,"contentHash":"sha256:a3cd40e567720144215a452cfa673dd2aa6c0be3ed5742e8f69549209ae66f29","question":"Look at the adjectives below meaning “wet.” Which word has the most intense meaning?","choices":["mo ist","damp","soggy","drenched"],"correct":3,"explanation":{"correct":"Answer: drenched. The word 'drenched' implies that something is completely soaked through with liquid, representing a much higher intensity than simply being slightly wet.","incorrect":[{"choice":"mo ist","reason":"\"mo ist\" does not match the sentence purpose described in the prompt."},{"choice":"damp","category":"mild intensity adjective","reason":"While 'damp' means something is a little bit wet, it does not suggest the total saturation that 'drenched' describes."},{"choice":"soggy","category":"moderate intensity adjective","reason":"A 'soggy' item is heavy with water and soft, but 'drenched' carries a stronger connotation of being thoroughly soaked through."},""]},"studyAid":{"definition":"Words that describe the same quality but with different levels of strength are called gradable adjectives. You can rank them from mild to extreme based on their intensity.","example":"damp (mild), wet (medium), soaked (strong), drenched (extreme).","strategyClue":"Imagine you dropped each word into the sentence 'I am completely ____.' Which word describes the state of being so full of water that no more could possibly fit?","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Advanced Quiz 2_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":4,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":31,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0032","version":3,"contentHash":"sha256:593aefaf5eabeba95a084709b23033c5276bd2871da890d60afd492011951c25","question":"Choose the correct way to write the underlined portion of the sentence below. The itsy bitsy spider is a well-known nursery rhyme still sung in households today.","choices":["“The Itsy Bitsy spider”","“The Itsy Bitsy Spider”","The Itsy Bitsy Spider","The Itsy Bitsy spider"],"correct":1,"explanation":{"correct":"Answer: “The Itsy Bitsy Spider”. Titles of nursery rhymes should be enclosed in quotation marks and use title case, where major words like 'Itsy', 'Bitsy', and 'Spider' are capitalized.","incorrect":[{"choice":"“The Itsy Bitsy spider”","category":"improper spacing and capitalization","reason":"This choice has an extra space in 'The' and fails to capitalize the word 'Spider', which is part of the official title."},"",{"choice":"The Itsy Bitsy Spider","category":"missing punctuation","reason":"Titles of short works like poems or nursery rhymes require quotation marks to clearly set them apart from the rest of the sentence."},{"choice":"The Itsy Bitsy spider","category":"incorrect capitalization and punctuation","reason":"This choice is missing the quotation marks and uses lowercase for 'spider', even though it is a key noun in the title."}]},"studyAid":{"definition":"Titles of short works such as poems, songs, and nursery rhymes should be enclosed in quotation marks, and all major words should begin with a capital letter.","example":"\"Twinkle, Twinkle, Little Star\" (nursery rhyme), \"The Star-Spangled Banner\" (song title), \"The Very Hungry Caterpillar\" (book title)","strategyClue":"Look at the list of options and check if the punctuation marks are placed correctly at the very beginning and very end of the title, then verify that every important word inside starts with a capital letter.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"passage-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Advanced Quiz 2_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":9,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":32,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0033","version":3,"contentHash":"sha256:33bd9e522fcba5b1b0bd1a2b297acc1efb7f9c85a62da7471170c8a57ed92b19","question":"Identify what type of sentence the following is. Why were you not present in class yesterday?","choices":["exclamatory","interrogative","imperative","declarative"],"correct":1,"explanation":{"correct":"Answer: interrogative. An interrogative sentence asks a direct question and ends with a question mark. Since this sentence is asking for information about someone's attendance, it is interrogative.","incorrect":[{"choice":"exclamatory","category":"incorrect sentence function","reason":"An exclamatory sentence expresses strong emotion and ends with an exclamation point. This sentence is seeking information rather than expressing a sudden, forceful feeling."},"",{"choice":"imperative","category":"incorrect sentence function","reason":"An imperative sentence gives a command or makes a request. This sentence does not tell someone to do something; it asks a question about the past."},{"choice":"declarative","category":"incorrect sentence function","reason":"A declarative sentence makes a statement or expresses an opinion. It ends with a period, whereas this sentence asks a question and requires an answer."}]},"studyAid":{"definition":"Sentences are classified by their purpose: interrogative sentences ask questions, declarative sentences state facts, imperative sentences give commands, and exclamatory sentences show strong emotion.","example":"Interrogative: Where is my bag? Declarative: The bag is blue. Imperative: Find your bag. Exclamatory: I found it!","strategyClue":"Look at the end punctuation and the purpose of the words. If the sentence is requesting an answer from someone, identify what kind of sentence structure serves that goal.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Advanced Quiz 3_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":33,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0034","version":3,"contentHash":"sha256:79baac1cd924c66c55f2eed2777c482b2a85e01feb30f53fdf2e45dff9dbf6d2","question":"Look at the letter below. Identify which line(s) contain an error. Febuary 5, 2020 (1) Dear Miranda, (2) Would you like to come visit next summer? (3 so much to do. (4) There is) We could go hiking, biking or ice skating. (5) We would have so much fun. (6) Your Friend, (7) Melissa","choices":["Line 2, 5, and 7","Line 1, 2, and 5","Line 1, 5, and 7","Line 5 and 7"],"correct":2,"explanation":{"correct":"Answer: Line 1, 5, and 7. 'Febuary' is a spelling error (should be February), line 5 lacks a capital letter to begin the sentence, and 'Your Friend' in a closing should not have a capital 'F'.","incorrect":[{"choice":"Line 2, 5, and 7","category":"incorrect error identification","reason":"Line 2 is written correctly with a capital letter and punctuation. The spelling error in line 1 is missing here."},{"choice":"Line 1, 2, and 5","category":"incorrect error identification","reason":"Line 2 is correct as written. The error in the closing (line 7) is not included in this choice."},"",{"choice":"Line 5 and 7","category":"missing spelling error","reason":"This choice misses the spelling mistake in line 1, where the month 'February' is missing its second 'r'."}]},"studyAid":{"definition":"A formal letter requires correct spelling of dates, proper capitalization at the start of sentences, and standard formatting for closings where only the first word is capitalized.","example":"February (not Febuary), Dear Friend (not Dear friend), Sincerely, (not Sincerely, Your friend)","strategyClue":"Check each line individually for three things: spelling of common words, capitalization of the first word in a sentence, and formal letter closing rules.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"passage-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Advanced Quiz 3_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":9,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":34,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0035","version":3,"contentHash":"sha256:f9d85de6dfeff21f07d14d187e5aed310d1dc6c38aafa6b1db1fc3345bdca347","question":"What is the purpose of an exclamatory sentence?","choices":["to explain something","to expand on an idea","to share an experience","to show emotion"],"correct":3,"explanation":{"correct":"Answer: to show emotion. An exclamatory sentence is specifically designed to express strong feelings like excitement, surprise, or anger.","incorrect":[{"choice":"to explain something","category":"declarative sentence type","reason":"Sentences that explain facts are usually declarative, not exclamatory. Declarative sentences end with a period rather than an exclamation point."},{"choice":"to expand on an idea","category":"descriptive writing function","reason":"Expanding on an idea is a writing technique used for details, but it does not describe the specific function of an exclamatory sentence's punctuation style."},{"choice":"to share an experience","category":"narrative writing purpose","reason":"You can share an experience using many types of sentences, but the defining goal of an exclamatory sentence is to emphasize your emotional reaction to that experience."},""]},"studyAid":{"definition":"An exclamatory sentence expresses strong emotion and always ends with an exclamation point (!).","example":"Correct: I won the race! Incorrect: I won the race.","strategyClue":"Look at the punctuation mark at the end of a sentence. If it ends in an exclamation point, ask yourself if the speaker is trying to state a simple fact or reveal how they are feeling.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Advanced Quiz 4_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":35,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0041","version":3,"contentHash":"sha256:5964476a49c801ad17d07d4d6733114f31749b7806aef8c75fabcd2594115360","question":"Choose the punctuation mark that is needed in the sentence. If no more punctuation is needed, choose “None.” Do you think the movie is scary","choices":[".","!","?","None"],"correct":2,"explanation":{"correct":"Answer: ?. This sentence is an interrogative sentence because it asks a direct question, 'Do you think the movie is scary?', which requires a question mark at the end.","incorrect":[{"choice":".","category":"incorrect sentence type","reason":"The period is used for statements, but since this sentence begins with 'Do', it is a question and needs a question mark instead."},{"choice":"!","category":"incorrect punctuation mark","reason":"An exclamation point shows strong emotion or surprise. This sentence is simply asking for an opinion, so a question mark is the correct choice."},"",{"choice":"None","category":"missing end punctuation","reason":"Every sentence needs an end mark. Without one, the reader cannot tell if the sentence is finished or if it is a statement, question, or exclamation."}]},"studyAid":{"definition":"A question mark is used at the end of a sentence that asks a question. A period is used at the end of a sentence that makes a statement.","example":"Where is my hat? (Question), I have a blue hat. (Statement), Did you see that? (Question)","strategyClue":"Look at the first word of the sentence. If the sentence starts with words like 'Do', 'Does', 'Is', 'Are', or 'What', ask yourself if you are waiting for an answer to be spoken back to you.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Basic Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":1,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":41,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0042","version":3,"contentHash":"sha256:27db4d4e651c0bf13ff6a2c35486b4305a8955d23d2b9eaabcd50c3e6cac0b8c","question":"Choose the line that has a punctuation error. If there is no error, choose “No mistakes.”","choices":["A bear has sharp claws","A large bear may weigh as","much as 900 pounds.","No mistakes"],"correct":0,"explanation":{"correct":"Answer: No mistakes. This sentence correctly follows the subject-verb-object structure and does not require any punctuation inside the clause. It is a complete, simple sentence.","incorrect":["",{"choice":"A large bear may weigh as","category":"fragmented sentence structure","reason":"Splitting the sentence here disrupts the flow of the verb phrase. A sentence should not be broken into pieces unless you are using specific punctuation like a dash or comma for a pause."},{"choice":"much as 900 pounds.","category":"incomplete sentence fragment","reason":"This phrase is missing the subject and the beginning of the predicate. It cannot stand alone as a sentence because it does not tell us who or what is weighing 900 pounds."},{"choice":"No mistakes","reason":"\"No mistakes\" has acceptable end punctuation, so it is not the error the prompt asks for."}]},"studyAid":{"definition":"A complete sentence must express a full thought and contain both a subject (who or what) and a predicate (what they are doing or being).","example":"Correct: The cat sat on the rug. Incorrect: The cat (missing action). Sat on the rug (missing subject).","strategyClue":"Read each line aloud to see if it forms a complete thought on its own. If the line feels like it is 'cutting off' the middle of a sentence, it is likely the source of the error.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Basic Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":2,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":42,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0044","version":4,"contentHash":"sha256:6127c7f9f5c5e6b74514ba2b7bb5367deaeeecc36595d8bbf1b7eacfc40a08c4","question":"Choose the best way to write the underlined portion of the sentence. If the underlined part is correct, choose “Correct as is.” Summers are hot in Las Vegas Nevada.","choices":["Las Vegas Nevada,","Las, Vegas Nevada.","Las Vegas, Nevada.","Correct as is."],"correct":2,"explanation":{"correct":"Answer: Las Vegas, Nevada. When writing the name of a city followed by its state, always place a comma after the city name and another comma after the state name if the sentence continues.","incorrect":[{"choice":"Las Vegas Nevada,","category":"missing internal comma","reason":"This option is missing the comma between the city and the state. A comma is required to separate the two locations."},{"choice":"Las, Vegas Nevada.","category":"misplaced comma","reason":"The comma should separate the city from the state, not split the city's name itself. 'Las Vegas' is one single place name."},"",{"choice":"Correct as is.","category":"missing required punctuation","reason":"The original sentence is missing the necessary comma between the city and state, so it is not correct as written."}]},"studyAid":{"definition":"When writing city and state names together, use a comma to separate the city from the state, and also place a comma after the state if the sentence continues.","example":"Correct: I live in Paris, France. Incorrect: I live in Paris France.","strategyClue":"Identify the city and the state in the sentence. Imagine a tiny pause between the two; that pause is exactly where the punctuation mark belongs.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"passage-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Basic Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":4,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":44,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0049","version":3,"contentHash":"sha256:41695ba0c9c4a4e0e8f9820921a59b57d819024ef260628e7e1b2b47ecacf8ca","question":"Which of the following sentences is punctuated correctly?","choices":["I like to ride my bike and my sister does as well.","I like to ride my bike, and my sister does as well.","I like to ride my bike; and my sister does as well.","I like to ride my bike. And my sister does as well."],"correct":1,"explanation":{"correct":"Answer: I like to ride my bike, and my sister does as well. When joining two complete sentences with a coordinating conjunction like 'and,' you must place a comma before the conjunction.","incorrect":[{"choice":"I like to ride my bike and my sister does as well.","category":"missing comma","reason":"This sentence joins two independent clauses with 'and' but fails to include the necessary comma before the conjunction to separate the two ideas."},"",{"choice":"I like to ride my bike; and my sister does as well.","category":"incorrect semicolon usage","reason":"You should not use a semicolon before a coordinating conjunction like 'and.' A comma is the standard punctuation mark to use in this structure."},{"choice":"I like to ride my bike. And my sister does as well.","category":"sentence fragment","reason":"Starting a sentence with a coordinating conjunction like 'And' is generally avoided in this context. It is better to connect these related ideas into one smooth sentence."}]},"studyAid":{"definition":"Use a comma followed by a coordinating conjunction (for, and, nor, but, or, yet, so) to join two independent clauses (complete sentences) together.","example":"I went to the store, and I bought bread. (Correct) / I went to the store and I bought bread. (Missing comma)","strategyClue":"Identify if the sentence has two subjects and two verbs that could stand alone as separate sentences. If they are linked by a joining word, look for the comma that signals the transition.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Basic Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":9,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":49,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0050","version":3,"contentHash":"sha256:215e239fa2a54d34055452a249af37973bec37cb484ec35731b85fc6b6c2ba91","question":"Identify what type of sentence the following sentence is. That was amazing!","choices":["exclamatory","interrogative","imperative","declarative"],"correct":0,"explanation":{"correct":"Answer: exclamatory. An exclamatory sentence expresses strong emotion or excitement and ends with an exclamation point, which fits this sentence perfectly.","incorrect":["",{"choice":"interrogative","category":"incorrect sentence type","reason":"An interrogative sentence asks a question and ends with a question mark. This sentence is a statement of feeling, not a question."},{"choice":"imperative","category":"incorrect sentence type","reason":"An imperative sentence gives a command or makes a request. Since no one is being told to do anything here, it cannot be imperative."},{"choice":"declarative","category":"incorrect sentence type","reason":"While a declarative sentence does make a statement, it usually ends with a period. Because this sentence expresses strong emotion and ends with an exclamation point, 'exclamatory' is the more specific and correct label."}]},"studyAid":{"definition":"Exclamatory sentences show strong feelings like surprise, joy, or anger and always end with an exclamation point (!).","example":"I won the race! That dog is so big! What a beautiful day!","strategyClue":"Look at the end punctuation of the sentence and ask yourself if the speaker is trying to share a calm fact or express a big feeling.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Basic Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":10,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":50,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0052","version":3,"contentHash":"sha256:bed5f5679c949cf595a237bcea71330d2aef5cc7caf07375f0083afbe9d2a462","question":"Choose the line that has a n err or. If there is no error, choo se “No mistakes.”","choices":["I fig ured out how to put","the puzzle together. it","on ly took me three days.","No mistakes"],"correct":1,"explanation":{"correct":"Answer: the puzzle together. it. The word 'it' should be capitalized because it starts a new sentence after the period. Sentences must always begin with a capital letter.","incorrect":[{"choice":"I fig ured out how to put","category":"correct capitalization","reason":"The pronoun 'I' is correctly capitalized, and no other words in this segment need special capitalization or punctuation changes."},"",{"choice":"on ly took me three days.","category":"correct sentence structure","reason":"This segment correctly follows the previous sentence and does not contain any errors in spelling or punctuation."},{"choice":"No mistakes","category":"identifying sentence errors","reason":"This choice is incorrect because there is a missing capital letter at the start of the second sentence."}]},"studyAid":{"definition":"Every new sentence must start with a capital letter. Proper punctuation, like a period, signals the end of one thought and the beginning of another.","example":"Correct: I love reading. It is fun. Incorrect: I love reading. it is fun.","strategyClue":"Look for all periods in the passage. Check the word immediately following each period to ensure it starts with an uppercase letter.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Basic Quiz 2_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":2,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":52,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0054","version":4,"contentHash":"sha256:498abd7bc4193682ea49b2a956127d4f10c4b64d239331dd4a678ce854130f84","question":"Choose the best way to write the underlined portion of the sentence. If the underlined part is correct, cho ose “Correct as is.” I like to ride my bike but my sister prefer s to ride a horse.","choices":["bike but,","bike. But","bike, but","Correct as is."],"correct":2,"explanation":{"correct":"Answer: bike, but. Use a comma before a coordinating conjunction (like 'but') when it joins two independent clauses that both have a subject and a verb.","incorrect":[{"choice":"bike but,","category":"misplaced comma","reason":"The comma should come before the coordinating conjunction 'but' to separate the two thoughts, not after it."},{"choice":"bike. But","category":"sentence fragment","reason":"While a period creates two separate sentences, adding a comma before 'but' is the standard way to connect these two related clauses into one smooth sentence."},"",{"choice":"Correct as is.","category":"missing punctuation","reason":"When you connect two full sentences with a word like 'but', you need to place a comma before that word to help the reader pause."}]},"studyAid":{"definition":"When joining two complete thoughts with a coordinating conjunction (for, and, nor, but, or, yet, so), place a comma before the conjunction.","example":"Correct: I was tired, but I finished my work. Incorrect: I was tired but I finished my work.","strategyClue":"Look for a subject and a verb on both sides of the conjunction. If both sides are complete sentences, place the comma before the connecting word.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"passage-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Basic Quiz 2_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":4,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":54,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0057","version":3,"contentHash":"sha256:c1ac389ee0237b38ec71be4996001c4ac9ac96bb4bf6cce5dd588a9f43b6f9f0","question":"Choose the word that best completes the sentence. Sheri was a(n) _______. She was full of energy and enthusiasm. She didn’t let anything get her down.","choices":["angel","bully","fireball","pistol"],"correct":2,"explanation":{"correct":"Answer: fireball. A 'fireball' is a common idiomatic expression for someone who is exceptionally energetic, enthusiastic, and spirited.","incorrect":[{"choice":"angel","category":"mismatched descriptive tone","reason":"While an angel is kind, the sentence specifically highlights high energy and enthusiasm, which 'fireball' captures much better."},{"choice":"bully","category":"inconsistent character trait","reason":"A bully is typically unkind or aggressive. This choice contradicts the positive energy and enthusiasm described in the sentence."},"",{"choice":"pistol","reason":"\"pistol\" does not match the sentence purpose described in the prompt."}]},"studyAid":{"definition":"Idioms are expressions where the meaning is different from the literal words, often used to paint a vivid picture of a person's personality.","example":"He is a night owl (stays up late). She is a social butterfly (likes to be around people). He is a fireball (full of energy).","strategyClue":"Look for the descriptive keywords in the surrounding sentences, such as 'energy' and 'enthusiasm,' then select the word that matches those specific traits.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Basic Quiz 2_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":7,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":57,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0061","version":4,"contentHash":"sha256:ef03a805005d4505f4ad22056acab5b7e50e4c2abf20e933365f745483bcc665","question":"Choose the punctuation mark that is needed in the sentence. If no more punctuation is needed, choose “None.” Katherine Matthew, and Paige all went to the carnival.","choices":[".","!",",","None"],"correct":2,"explanation":{"correct":"Answer: ,. You need a comma after 'Matthew' because this sentence contains a list of three people: Katherine, Matthew, and Paige. Use commas to separate three or more items in a series.","incorrect":[{"choice":".","category":"incorrect sentence termination","reason":"A period ends a complete sentence. Placing one after 'Matthew' creates a sentence fragment and stops the flow of the list mid-sentence."},{"choice":"!","category":"incorrect punctuation mark","reason":"An exclamation mark is used to show strong emotion or excitement. It is not used to separate items in a list of names."},"",{"choice":"None","category":"missing list comma","reason":"When you list three or more items, you must separate them with commas so the reader knows where one name ends and the next begins."}]},"studyAid":{"definition":"When listing three or more items in a sentence, use commas to separate each item from the next one.","example":"I bought apples, oranges, and pears. My favorite colors are red, blue, and green.","strategyClue":"Count the number of items being mentioned in the sentence. If there are three or more, identify the items to see where the natural pauses should go.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"passage-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Basic Quiz 3_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":1,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":61,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0062","version":4,"contentHash":"sha256:5e49b4e7252c76afa67a0e17ca10ec42645059a4489fc111cf5f2677a962de7b","question":"Choose the line that has a punctuation error. If there is no error, choose “No mistakes.”","choices":["Thomas called his mother.","He forgot his homework again,","and knew hed be in trouble with his teacher.","No mistakes"],"correct":2,"explanation":{"correct":"Answer: and knew hed be in trouble with his teacher. This sentence contains an error because 'hed' is a contraction of 'he would' or 'he had' and requires an apostrophe between the 'e' and the 'd'.","incorrect":[{"choice":"Thomas called his mother.","category":"correct punctuation","reason":"This sentence is punctuated correctly. It uses a capital letter for a proper noun and a period at the end of the sentence."},{"choice":"He forgot his homework again,","category":"correct punctuation","reason":"This sentence is punctuated correctly. A comma is used appropriately to separate a dependent clause or add a pause at the end of the thought."},"",{"choice":"No mistakes","category":"missing error detection","reason":"There is a mistake in the other option regarding the missing apostrophe in a contraction, so 'No mistakes' is not the correct selection."}]},"studyAid":{"definition":"Contractions are two words joined together by an apostrophe that replaces the missing letters. Without the apostrophe, the word is often spelled incorrectly.","example":"He'd (he would/he had), it's (it is), you're (you are)","strategyClue":"Look for words that are combinations of two smaller words (like pronouns and verbs). Check if they contain the punctuation mark that shows letters were removed.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Basic Quiz 3_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":2,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":62,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0064","version":4,"contentHash":"sha256:34a69df235bab07bb4826600d89aeb6b5a507a66e25210372ea330b97b8e21ac","question":"Choose the best way to write the underlined portion of the sentence. If the underlined part is correct, choose “Correct as is.” “Turn down the volume on the radio” yelled Noah’s mother.","choices":["rad io,” yelled","radio.” Yelled","radio.” yelled","Correct as is."],"correct":0,"explanation":{"correct":"Answer: radio,” yelled. When a sentence is interrupted by a dialogue tag, the first part ends with a comma inside the quotation marks, and the dialogue tag begins with a lowercase letter.","incorrect":["",{"choice":"radio.” Yelled","category":"period after dialogue","reason":"Using a period inside the quotes suggests the sentence has ended. Since the dialogue tag 'yelled' is part of the same sentence, use a comma instead."},{"choice":"radio.” yelled","category":"period after dialogue","reason":"A period ends a complete sentence. Because the speaker's words are continuing through the dialogue tag, the punctuation inside the quotation marks must be a comma."},{"choice":"Correct as is.","category":"missing punctuation","reason":"The original sentence is missing the necessary comma to separate the spoken words from the dialogue tag 'yelled'."}]},"studyAid":{"definition":"When a dialogue tag follows a quote that is part of a larger sentence, use a comma inside the closing quotation mark and keep the dialogue tag lowercase.","example":"\"It is time,\" said Mom. \"Wait for me!\" she shouted.","strategyClue":"Ask yourself if the speaker's words are a full, separate sentence or if they are being interrupted by the tag. If the tag completes the thought, replace the period with a comma.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"passage-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Basic Quiz 3_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":4,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":64,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0069","version":3,"contentHash":"sha256:83b1aeaaca450370a009b0c2a1aab43179c44f9cff182ffe6421a75a06fcbd78","question":"What would be the correct punctuation to end the following sentence? Put your book down","choices":[". (period)","! (exclamation)","? (question)","None"],"correct":0,"explanation":{"correct":"Answer: . (period). The sentence 'Put your book down' is an imperative sentence, which is a command or a request. Imperative sentences should end with a period unless they express strong emotion or urgency.","incorrect":["",{"choice":"! (exclamation)","category":"exclamation point usage","reason":"An exclamation point is used for strong feelings or surprise. Unless you are shouting the command loudly, a simple instruction should end with a period."},{"choice":"? (question)","category":"question mark usage","reason":"A question mark is used only when asking for information. 'Put your book down' does not ask a question, so a question mark would be incorrect."},{"choice":"None","category":"missing end punctuation","reason":"Every complete sentence must end with a punctuation mark. Without one, the reader won't know where the thought finishes."}]},"studyAid":{"definition":"Use a period at the end of a command or request, which is known as an imperative sentence.","example":"Correct: Please sit down. Incorrect: Please sit down? / Please sit down!","strategyClue":"Ask yourself if the speaker is trying to get information, shout, or simply give an instruction. If it is an instruction, choose the mark used for a standard statement.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Basic Quiz 3_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":9,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":69,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0072","version":3,"contentHash":"sha256:54e86278674196e548d9837e3f84b63596c6c93241b8e96ae234d1d0ed48a8f5","question":"Read the sentence below. Then choose the line that has a punctuation error. If there is no error, choose “No mistakes.” I learned how to do my own laundry. It wasn’t as difficult as I thought it would be.","choices":["Ile arned how to do","my own laundry. It wasn’t","as difficult as I thought it would be.","No mistakes"],"correct":3,"explanation":{"correct":"Answer: No mistakes. The sentence uses correct capitalization, proper punctuation for the contraction 'wasn’t', and accurate end-mark usage throughout the text.","incorrect":[{"choice":"Ile arned how to do","category":"incorrect spacing","reason":"This choice incorrectly breaks the word 'learned' by inserting a space, which creates two separate letter groups instead of one verb."},{"choice":"my own laundry. It wasn’t","category":"misidentified punctuation error","reason":"The period after 'laundry' correctly separates two complete thoughts, and the apostrophe in 'wasn’t' is placed correctly to show the missing 'o' in 'was not'."},{"choice":"as difficult as I thought it would be.","category":"misidentified punctuation error","reason":"The sentence structure is complete and the period at the end is correctly placed to show the finish of the thought."},""]},"studyAid":{"definition":"A sentence is complete when it expresses a full thought and ends with a period, question mark, or exclamation point. Contractions like 'wasn't' need an apostrophe where the letter was removed.","example":"Correct: I can't wait. Incorrect: I cant wait. Correct: The dog ran. Incorrect: The dog ran","strategyClue":"Check each line for missing capital letters at the start, check that contractions have an apostrophe, and ensure every complete sentence has an ending punctuation mark.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"passage-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Basic Quiz 4_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":2,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":72,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0086","version":3,"contentHash":"sha256:ccb493152460963d43696c21c2dd494bd8182c6dc5ae15587c913108cca11bfa","question":"Which sentence has the correct punctuation?","choices":["The girls stood around chatting, and teasing each other.","My brothers were watching a movie last night when, they heard a loud bang.","We all ran for the door, and Hilda rushed to open it.","We glanced at each other and, Kelsey burst into tears."],"correct":2,"explanation":{"correct":"Answer: We all ran for the door, and Hilda rushed to open it. This sentence correctly uses a comma before the coordinating conjunction 'and' to connect two complete, independent thoughts.","incorrect":[{"choice":"The girls stood around chatting, and teasing each other.","category":"unnecessary comma","reason":"You should not place a comma between two verb phrases if they share the same subject. The comma separates the action of 'chatting' from 'teasing,' which makes the sentence flow poorly."},{"choice":"My brothers were watching a movie last night when, they heard a loud bang.","category":"misplaced comma","reason":"The comma is incorrectly placed between the word 'when' and the rest of the clause. Commas should only be used to separate independent clauses or set off extra information, not to break up the middle of a phrase."},"",{"choice":"We glanced at each other and, Kelsey burst into tears.","category":"misplaced comma","reason":"In this sentence, the comma is placed after the word 'and,' which is incorrect. A comma before a conjunction should come before the word, not after it."}]},"studyAid":{"definition":"A comma is used before a coordinating conjunction (like 'and', 'but', or 'or') only when it connects two complete sentences that could stand alone.","example":"He ate a snack, and he felt better. (Correct) vs. He ate a snack and felt better. (Correct - no comma needed for shared subject)","strategyClue":"Check if there is a full sentence on both sides of the 'and'. If you have a subject and a verb on both sides, the comma belongs before the 'and'. If the second part is just an extra action, you don't need a comma.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Proficient Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":6,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":86,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0094","version":3,"contentHash":"sha256:890044bbe245dd85013b8ff048edc2c30f3509147085cedaab5e84f3c0a94387","question":"Read the sentence below. Then choose a more precise and descriptive word to replace the underlined word in the sentence. The cat crawled along the grass, desperate not to be seen.","choices":["slit hered","moved","walked","leapt"],"correct":0,"explanation":{"correct":"Answer: slithered. The word 'slithered' is more precise than 'crawled' because it specifically describes the low, smooth, and quiet movement of a cat staying hidden close to the ground.","incorrect":["",{"choice":"moved","category":"vague word choice","reason":"'Moved' is a general action word that doesn't explain how the cat traveled. It fails to convey the stealthy, low-to-the-ground action required for someone trying not to be seen."},{"choice":"walked","category":"imprecise verb choice","reason":"When an animal is trying not to be seen, 'walked' is too normal. It suggests a standard upright gait rather than the careful, hidden movement described in the sentence."},{"choice":"leapt","category":"inaccurate verb choice","reason":"Leaping is a sudden, high-energy movement. Since the cat is trying not to be seen, leaping would likely draw too much attention and does not fit the stealthy context."}]},"studyAid":{"definition":"Precise verbs give the reader a clearer picture of an action by showing exactly how it happened rather than just stating that it happened.","example":"Instead of 'The boy went down the hall,' use 'The boy tiptoed down the hall' or 'The boy marched down the hall.'","strategyClue":"Think about the character's goal in the sentence. Ask yourself, 'What specific motion best matches someone trying to stay hidden or quiet?'","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"passage-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Proficient Quiz 2_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":4,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":94,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0095","version":3,"contentHash":"sha256:b4155a917854286f11227e2448f47da8376cbbfb3051d835961173bfafa940f6","question":"Identify what type of sentence the following is. I have too much homework to do.","choices":["exclamatory","interrogative","imperative","declarative"],"correct":3,"explanation":{"correct":"Answer: declarative. A declarative sentence makes a statement or expresses an opinion and always ends with a period. This sentence tells us about a fact regarding the amount of homework.","incorrect":[{"choice":"exclamatory","category":"incorrect sentence type","reason":"Exclamatory sentences express strong emotion and end with an exclamation point. Since this sentence simply states a fact, it is not exclamatory."},{"choice":"interrogative","category":"incorrect sentence type","reason":"Interrogative sentences ask a question and end with a question mark. This sentence does not seek information or ask for an answer."},{"choice":"imperative","category":"incorrect sentence type","reason":"Imperative sentences give a command or request. This sentence does not tell anyone to do anything, so it cannot be imperative."},""]},"studyAid":{"definition":"A declarative sentence is a sentence that tells the reader information or states a fact, usually ending with a period.","example":"Declarative: The sky is blue. / Not declarative: Is the sky blue? (Interrogative) / Look at the sky! (Imperative)","strategyClue":"Look at the end punctuation and the purpose of the sentence. Ask yourself if the sentence is asking for an answer, giving a command, showing strong excitement, or simply providing information.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Proficient Quiz 2_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":95,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0105","version":3,"contentHash":"sha256:d25bf161fcc0d211e78a72b4fe9833d4076a5901aa1d7b447cb4afc47fe93b0f","question":"Identify what type of sentence the following is. Wash the dishes now so they will be clean for dinner.","choices":["exclamatory","interrogative","imperative","declarative"],"correct":2,"explanation":{"correct":"Answer: imperative. This sentence is a command or instruction given to the listener. Imperative sentences often begin with a verb and imply the subject 'you'.","incorrect":[{"choice":"exclamatory","category":"incorrect sentence type","reason":"Exclamatory sentences show strong emotion or surprise and end with an exclamation point. This sentence is a calm instruction."},{"choice":"interrogative","category":"incorrect sentence type","reason":"Interrogative sentences ask a question and end with a question mark. This sentence does not ask for information."},"",{"choice":"declarative","category":"incorrect sentence type","reason":"Declarative sentences state a fact or opinion and end with a period. While this ends with a period, it functions as a request rather than a simple statement."}]},"studyAid":{"definition":"An imperative sentence gives a command, a request, or an instruction, and it usually ends with a period.","example":"Correct: 'Close the door.' Incorrect: 'The door is closed.' (Declarative)","strategyClue":"Look at the beginning of the sentence to see if it starts with a verb and try to determine if the speaker is telling someone else to do an action.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Proficient Quiz 3_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":105,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0115","version":3,"contentHash":"sha256:1578a1433a64c0101f9d88d885b646f620688614b86e2555d9707d96440bbf2b","question":"Identify what type of sentence the following is. Did you wash your hands before dinner?","choices":["exclamatory","interrogative","imperative","declarative"],"correct":1,"explanation":{"correct":"Answer: interrogative. An interrogative sentence is used to ask a question. Because this sentence asks for information and ends with a question mark, it is classified as interrogative.","incorrect":[{"choice":"exclamatory","category":"incorrect sentence type","reason":"Exclamatory sentences express strong emotion or excitement and usually end with an exclamation point, not a question mark."},"",{"choice":"imperative","category":"incorrect sentence type","reason":"Imperative sentences give a command or request. This sentence asks a question to get an answer rather than telling someone what to do."},{"choice":"declarative","category":"incorrect sentence type","reason":"A declarative sentence simply makes a statement or expresses an opinion. It does not ask a question or require an answer like this sentence does."}]},"studyAid":{"definition":"An interrogative sentence asks a direct question and always ends with a question mark.","example":"Where are my shoes? (Interrogative) vs. Put on your shoes. (Imperative)","strategyClue":"Look at the punctuation mark at the end of the sentence and determine the purpose of the sentence—is it stating a fact, giving a command, or seeking information?","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Proficient Quiz 4_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":115,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0055","version":3,"contentHash":"sha256:a3b89f800e1f82af135b338a0c15e1638fdd2d7afb2a7ae256fe3082feaa1a48","question":"Read the sentence carefully. Determine the appropriate ending punctuation. Oh dear, my favorite sweatshirt is completely ruined __","choices":["Statement (.)","Questions (?)","Exclamation (!)","Command (!)"],"correct":2,"explanation":{"correct":"Answer: Exclamation (!). The phrase 'Oh dear' expresses a strong feeling or sudden emotion, which requires an exclamation point to show the intensity of the speaker's reaction.","incorrect":[{"choice":"Statement (.)","category":"Incorrect terminal punctuation","reason":"A period is used for neutral, calm sentences. Because the speaker is upset about their ruined sweatshirt, a period does not match the emotional tone."},{"choice":"Questions (?)","category":"Question mark error","reason":"A question mark is only used when asking something. Since the sentence is expressing sadness rather than asking for information, a question mark is not appropriate."},"",{"choice":"Command (!)","category":"Incorrect punctuation label","reason":"While this option uses the correct symbol, 'Command' is a type of sentence, not an punctuation mark. Always look for the name of the symbol itself."}]},"studyAid":{"definition":"An exclamation point (!) is used at the end of a sentence to show strong feelings like excitement, surprise, fear, or anger.","example":"I won the race! Watch out for that car! That is the best news ever!","strategyClue":"Read the sentence out loud and imagine how an actor would say it; if you are shouting or expressing a powerful emotion, look for the mark that signals high energy.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","vocabulary and usage","language","grade 4"],"feedbackFocus":"use the word clue, word part, or usage rule to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Advanced Quiz 1_Language_Vocabulary and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":2,"sourceCategory":"vocabulary-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":55,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0056","version":3,"contentHash":"sha256:3da97cdb8ec374f6697824603c6ad13dd4dca1ef1d42b68db3dbc413c8657436","question":"Which of the following is not punctuated correctly?","choices":["Oh my!","I cannot believe I got so lucky!","Why do you always have to complain!","Get out of my chair, now!"],"correct":2,"explanation":{"correct":"Answer: Why do you always have to complain!. This sentence is a direct question and requires a question mark at the end rather than an exclamation point.","incorrect":[{"choice":"Oh my!","category":"interjection punctuation","reason":"This is an interjection showing strong emotion, so an exclamation point is the correct mark to use here."},{"choice":"I cannot believe I got so lucky!","category":"exclamatory sentence","reason":"This sentence expresses strong surprise and excitement, making the exclamation point the appropriate choice."},"",{"choice":"Get out of my chair, now!","category":"imperative punctuation","reason":"This is a strong command or demand. Using an exclamation point shows the urgency or forcefulness of the speaker's tone."}]},"studyAid":{"definition":"Sentences end with different marks based on their purpose: periods for statements, question marks for inquiries, and exclamation points for strong emotion or commands.","example":"Where is my hat? (Question), Stop running! (Command), I love pizza. (Statement)","strategyClue":"Read the sentence out loud and ask yourself: 'Am I asking for information, or am I expressing a strong feeling or giving an order?' Choose the punctuation that matches your tone.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","vocabulary and usage","language","grade 4"],"feedbackFocus":"use the word clue, word part, or usage rule to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Advanced Quiz 2_Language_Vocabulary and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":2,"sourceCategory":"vocabulary-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":56,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0058","version":3,"contentHash":"sha256:e5ebd440911b9e75510850f08e085df4f91d61eb79648042521f50165022be91","question":"Choose the sentence that is punctuated correctly.","choices":["After lunch, I need to go by the store, to buy some bread.","My brother ran into the kitchen, and he threw his books on the counter.","I love peanut butter and jelly sandwiches but I don’t like peanut butter and bananas.","Before I start the car I always put my seat belt on."],"correct":1,"explanation":{"correct":"Answer: My brother ran into the kitchen, and he threw his books on the counter. This sentence correctly uses a comma before a coordinating conjunction ('and') to connect two independent clauses.","incorrect":[{"choice":"After lunch, I need to go by the store, to buy some bread.","category":"unnecessary comma usage","reason":"There is no need for a comma before 'to buy'. You should only use a comma to separate phrases when they are part of a list or set off by a conjunction."},"",{"choice":"I love peanut butter and jelly sandwiches but I don’t like peanut butter and bananas.","category":"missing comma before conjunction","reason":"When you join two complete sentences with a word like 'but', you must place a comma before the conjunction to correctly separate the two thoughts."},{"choice":"Before I start the car I always put my seat belt on.","category":"missing introductory comma","reason":"When a sentence starts with a dependent clause like 'Before I start the car', you must place a comma after it to show where the introductory phrase ends."}]},"studyAid":{"definition":"Use a comma before a coordinating conjunction (for, and, nor, but, or, yet, so) that joins two independent, complete sentences.","example":"He wanted to go to the park, but it was raining. She finished her homework, and she went outside to play.","strategyClue":"Check each side of the coordinating conjunction. If both sides are full sentences that can stand alone, insert a comma right before the conjunction.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_ Proficient 1_4th grade.pdf","sourceQuestionNumber":2,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":58,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0059","version":3,"contentHash":"sha256:f10de7cc983f16e015be92b8c68718db07cee7b4b8f23ddbb1b417cd8e26ceea","question":"Look at the sentence below. Correctly name the type of sentence. The coffee is hot!","choices":["exclamatory","interrogative","imperative","declarative"],"correct":0,"explanation":{"correct":"Answer: exclamatory. An exclamatory sentence expresses strong emotion or surprise and ends with an exclamation point, which is exactly what 'The coffee is hot!' does.","incorrect":["",{"choice":"interrogative","category":"question type error","reason":"An interrogative sentence asks a question and ends with a question mark. Since this sentence ends with an exclamation point, it is not a question."},{"choice":"imperative","category":"command type error","reason":"An imperative sentence gives a command or request. This sentence describes the state of the coffee rather than telling someone to do something."},{"choice":"declarative","category":"statement type error","reason":"A declarative sentence makes a statement and ends with a period. While this sentence does state a fact, the exclamation point indicates strong feeling, making it exclamatory instead."}]},"studyAid":{"definition":"Exclamatory sentences communicate strong feelings like excitement, surprise, or urgency and must end with an exclamation point.","example":"I am so happy! That was a close one! Watch out for the truck!","strategyClue":"Look at the final punctuation mark at the end of the sentence. If it shows strong emotion instead of just a period or question mark, identify the sentence type based on that feeling.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_ Proficient 1_4th grade.pdf","sourceQuestionNumber":44,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":59,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0065","version":3,"contentHash":"sha256:091ef8c89381998d9ac0ff4b05e65e6bd4fd1e1bb22e974e76906ba42c003800","question":"Choose the sentence that shows correct punctuation.","choices":["Jen rode ten miles on her bike before stopping for lunch and a nap.","Jen rode ten miles on her bike, before stopping for lunch, and a nap.","Jen rode ten miles on her bike before stopping, for lunch and a nap.","Jen rode ten miles on her bike before stopping for lunch, and a nap."],"correct":0,"explanation":{"correct":"Answer: Jen rode ten miles on her bike before stopping for lunch and a nap. In this sentence, there is no need for a comma because the prepositional phrases 'for lunch' and 'a nap' form a simple compound object connected by 'and' without a pause.","incorrect":["",{"choice":"Jen rode ten miles on her bike, before stopping for lunch, and a nap.","category":"unnecessary comma usage","reason":"The comma before 'before' interrupts the flow of the sentence, and the comma before 'and' is unnecessary because it is not separating items in a complex list."},{"choice":"Jen rode ten miles on her bike before stopping, for lunch and a nap.","category":"misplaced comma","reason":"The comma after 'stopping' incorrectly splits the action from the purpose of the action. It makes the sentence feel disjointed."},{"choice":"Jen rode ten miles on her bike before stopping for lunch, and a nap.","category":"comma before conjunction","reason":"You generally do not need a comma before 'and' when it is just connecting two nouns at the end of a sentence. It creates an unnatural pause."}]},"studyAid":{"definition":"Commas are used to separate items in a list or to connect independent clauses, but they should not be used to break up simple phrases where no pause is needed.","example":"Correct: I like apples and oranges. Incorrect: I like apples, and oranges.","strategyClue":"Read each sentence out loud slowly. If your voice naturally pauses at a comma, it might be correct; if the comma forces you to stop where the sentence should flow smoothly, it is likely unnecessary.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_ Proficient 2_4th grade.pdf","sourceQuestionNumber":14,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":65,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0060","version":3,"contentHash":"sha256:a6fb3550a9a27eb9eeda9e4a7590dc8f3962427e068915dc1300ace1b6f0d31a","question":"What type of sentence is this? I need you to come here right now!","choices":["exclamatory","declarative","interrogative","imperative"],"correct":3,"explanation":{"correct":"Answer: imperative. This sentence gives a direct command or request. Even though it ends with an exclamation point for emphasis, the core purpose of the sentence is to tell someone what to do.","incorrect":[{"choice":"exclamatory","category":"confusing punctuation and purpose","reason":"While this sentence ends in an exclamation point, the sentence type depends on its purpose. Because it is a command rather than just a strong expression of emotion, it is classified as imperative."},{"choice":"declarative","category":"statement vs command","reason":"A declarative sentence tells information or shares a fact. This sentence is different because it is directing someone to take an action."},{"choice":"interrogative","category":"question vs command","reason":"An interrogative sentence asks a question and typically ends with a question mark. This sentence does not ask for information, so it is not interrogative."},""]},"studyAid":{"definition":"An imperative sentence gives a command, makes a request, or gives an instruction, often starting with a verb.","example":"Clean your room. (Command) Please pass the salt. (Request) Turn left at the corner. (Instruction)","strategyClue":"Ask yourself: 'Is the speaker giving an order or asking someone to do something?' If the sentence directs an action rather than stating a fact or asking a question, it is likely an imperative sentence.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_ Proficient 2_4th grade.pdf","sourceQuestionNumber":44,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":60,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0107","version":3,"contentHash":"sha256:4758c84b0c33929255aab8daedec660617db450bcc5ef577e648b0467ced3c9c","question":"Choose the sentence that has a punctuation error.","choices":["Leonard wants to buy a new PS4, but his mother won’t let him.","Joshua wanted to go to ride go carts and play putt putt.","Aaron and Arnold joined boy scouts; Loretta and Liza joined girl scouts.","Drake spent all day raking the leaves, but forgot to bag them."],"correct":3,"explanation":{"correct":"Answer: Drake spent all day raking the leaves, but forgot to bag them. This sentence is grammatically correct. It uses a comma before the coordinating conjunction 'but' to join two independent clauses.","incorrect":[{"choice":"Leonard wants to buy a new PS4, but his mother won’t let him.","category":"correct punctuation","reason":"This sentence is actually correct. The comma correctly separates two independent clauses joined by 'but'. The prompt asks to find the sentence with an error."},{"choice":"Joshua wanted to go to ride go carts and play putt putt.","category":"missing punctuation","reason":"This sentence is missing hyphens. Compound adjectives like 'go-carts' and 'putt-putt' need hyphens to show the words work together as one idea."},{"choice":"Aaron and Arnold joined boy scouts; Loretta and Liza joined girl scouts.","category":"correct punctuation","reason":"This sentence uses a semicolon correctly to connect two related independent clauses. It does not contain a punctuation error."},""]},"studyAid":{"definition":"Hyphens are used to join two words that act as a single adjective or to represent compound nouns that are written as one idea.","example":"well-known person, long-term goal, merry-go-round, putt-putt","strategyClue":"Look for words that are often paired together as compound nouns or adjectives. If you see two short, related words describing one thing, check to see if they should be linked with a hyphen.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_Advanced 1_4th grade.pdf","sourceQuestionNumber":5,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":107,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0118","version":4,"contentHash":"sha256:5f90bcedf15da96717f7a283d5b6b1901f079ddb1cfe14eb532e6a80ea0d8284","question":"What would transform this fragment into a complete sentence? Three ways to make good grades.","choices":["Replacing the period with a question mark at the end of the sentence.","Adding “attend class, stay organized, and study” to the end of the sentence.","Adding “There are” to the beginning of the sentence.","Nothing. The sentence is complete already."],"correct":2,"explanation":{"correct":"Answer: Adding “There are” to the beginning of the sentence. This creates a complete thought by providing a subject and a verb that connect to the phrase 'three ways to make good grades.'","incorrect":[{"choice":"Replacing the period with a question mark at the end of the sentence.","category":"improper punctuation change","reason":"Simply changing the ending punctuation does not add the missing subject or verb needed to turn a fragment into a complete sentence."},{"choice":"Adding “attend class, stay organized, and study” to the end of the sentence.","category":"adds more fragments","reason":"While this adds interesting information, it does not provide the main subject and verb required to give the sentence a clear action or state of being."},"",{"choice":"Nothing. The sentence is complete already.","category":"identifying sentence fragments","reason":"A sentence needs a subject and a predicate to be complete. 'Three ways to make good grades' tells us what the topic is, but not what is happening or existing about it."}]},"studyAid":{"definition":"A complete sentence must express a full thought and contain at least one subject (who or what) and one predicate (the action or state of being).","example":"Fragment: 'Running to the park.' Complete: 'He is running to the park.' Fragment: 'The big, red ball.' Complete: 'The big, red ball is mine.'","strategyClue":"Ask yourself: 'Who or what is doing something, and what are they doing?' If you cannot answer both parts, the sentence is missing a subject or a verb.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_Advanced 1_4th grade.pdf","sourceQuestionNumber":16,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":118,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0167","version":3,"contentHash":"sha256:3cb34fd7c397098e2a3d58ccdf9fae4858cca6c0533518d505c77f4548e6036b","question":"Choose the sentence that shows correct punctuation.","choices":["Douglas Browne, MD, worked in the Cooper Building in Marston, Illinois.","Douglas Browne, M.D., worked in the Cooper Building in Marston Illinois.","Douglas Browne, M.D., the Cooper Marston, Illinois. worked in Building in","Douglas Browne, M.D, worked in the Cooper Building in Marston, Illinois."],"correct":2,"explanation":{"correct":"Answer: Douglas Browne, MD, worked in the Cooper Building in Marston, Illinois. This sentence correctly places periods after the title abbreviation 'MD' and uses a comma to separate the city from the state.","incorrect":[{"choice":"Douglas Browne, MD, worked in the Cooper Building in Marston, Illinois.","reason":"\"Douglas Browne, MD, worked in the Cooper Building in Marston, Illinois.\" does not match the sentence purpose described in the prompt."},{"choice":"Douglas Browne, M.D., worked in the Cooper Building in Marston Illinois.","category":"missing comma in location","reason":"This sentence misses a vital comma. When you list a city and state, you must place a comma between them to separate the two locations."},"",{"choice":"Douglas Browne, M.D, worked in the Cooper Building in Marston, Illinois.","category":"missing abbreviation period","reason":"The abbreviation 'M.D.' requires a period after both the M and the D. Leaving out the second period makes the abbreviation incomplete."}]},"studyAid":{"definition":"Abbreviations for titles often require periods, and geographic locations like city and state names must be separated by a comma.","example":"Correct: Dr. Smith, Atlanta, Georgia. Incorrect: Dr Smith, Atlanta Georgia.","strategyClue":"Look for two things: do the letters in the title have a period after each one, and is there a comma separating the smaller place from the larger place?","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_Advanced 2_4th grade.pdf","sourceQuestionNumber":14,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":167,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0197","version":3,"contentHash":"sha256:912d5bf76ddceef64ca0753700625fe5da5c7b10dc2e291de0eb9bca286d9b36","question":"What type of sentence is this? Last week, my mom told me to buy some milk on my way home.","choices":["declarative","interrogative","exclamatory","imperative"],"correct":0,"explanation":{"correct":"Answer: declarative. A declarative sentence makes a statement or expresses an opinion and ends with a period. This sentence simply tells the reader information about what mom said.","incorrect":["",{"choice":"interrogative","category":"interrogative sentence type","reason":"An interrogative sentence asks a direct question and ends with a question mark. Since this sentence does not ask for information, it is not interrogative."},{"choice":"exclamatory","category":"exclamatory sentence type","reason":"An exclamatory sentence expresses strong emotion or excitement and ends with an exclamation point. This sentence uses a neutral tone and ends with a period."},{"choice":"imperative","category":"imperative sentence type","reason":"An imperative sentence gives a command or makes a request. While the sentence mentions a command given by mom, the whole sentence itself is just reporting that event as a fact."}]},"studyAid":{"definition":"A declarative sentence is a simple statement that gives information. It always ends with a period.","example":"The dog is sleeping. (Declarative) vs. Is the dog sleeping? (Interrogative)","strategyClue":"Look at the end punctuation mark and ask yourself if the speaker is trying to get information, give a command, or just state a fact.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_Advanced 2_4th grade.pdf","sourceQuestionNumber":44,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":197,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0206","version":3,"contentHash":"sha256:63f23c63a4f15409bcfb7b161b30de726705109f5a28e5450c1d0e8da69c9ef2","question":"Choose the punctuation mark that in the sentence. If punctuation is is needed no more needed, choose “None.” Our family played putt putt golf this weekend to celebrate my brother’s birthday","choices":["?","!",".","None"],"correct":2,"explanation":{"correct":"Answer: .. The sentence is a statement of fact that tells the reader what the family did, so it requires a period to mark the end of the thought.","incorrect":[{"choice":"?","category":"incorrect end punctuation","reason":"A question mark is only used for sentences that ask for information. Since this sentence provides information, a question mark is not appropriate."},{"choice":"!","category":"incorrect end punctuation","reason":"An exclamation point is used for strong emotions or shouting. Unless the writer feels extreme excitement about the golf trip, a period is the standard choice."},"",{"choice":"None","category":"missing end punctuation","reason":"Every complete sentence must end with a punctuation mark to show where the thought stops. Omitting it leaves the sentence unfinished."}]},"studyAid":{"definition":"Sentences that state a fact or describe an action always end with a period. A period acts like a stop sign for the reader.","example":"I like pizza. We went to the park. The dog barked.","strategyClue":"Read the sentence out loud and ask yourself: 'Am I asking a question or just sharing information?' If you are sharing information, look for the choice that ends the sentence calmly.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":2,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":206,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0212","version":3,"contentHash":"sha256:da4f7db7cf80e74736a85ee5a94098a5e7d3ba63acaefaca47727122f812c17d","question":"Choose the that fits the blank and the punctuation. word best in shows correct The speakers were blaring so loud that they were vibrating.","choices":["stereos","stereo’s","stereos’","stereos’s"],"correct":1,"explanation":{"correct":"Answer: stereo’s. Use an apostrophe followed by 's' to show possession for a singular noun. Since only one stereo is causing the vibration, 'stereo’s' is the correct form.","incorrect":[{"choice":"stereos","category":"missing apostrophe","reason":"This is simply the plural form of the word. It does not show that the speakers belong to the stereo, which is required here."},"",{"choice":"stereos’","category":"incorrect plural possessive","reason":"The apostrophe at the end is for plural words that already end in 's'. Since we are talking about one stereo, this punctuation is incorrect."},{"choice":"stereos’s","category":"incorrect spelling","reason":"This form is incorrect because it tries to combine a plural ending with a possessive ending. Stick to the singular possessive form for a single object."}]},"studyAid":{"definition":"To show that something belongs to a singular noun, add an apostrophe and an 's' to the end of the word.","example":"The dog's bowl (one dog), The cat's toy (one cat), The stereo's sound (one stereo).","strategyClue":"Ask yourself: Is there one item or more than one? If there is only one item and it owns something else in the sentence, use the apostrophe before the 's'.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":8,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":212,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0227","version":3,"contentHash":"sha256:d1fb81a8d5b00e7e8e0c42ce7016e966f3bef518306ba439445c39ac3b8b0e35","question":"Which of the following sentences is punctuated correctly?","choices":["I love to but my sister despises it. go shopping","I love to go shopping; but my sister despises it.","I love to go shopping. But my sister despises it.","I love to go shopping, but my sister despises it."],"correct":3,"explanation":{"correct":"Answer: I love to go shopping, but my sister despises it. When using a coordinating conjunction like 'but' to join two independent clauses, you must place a comma before the conjunction.","incorrect":[{"choice":"I love to but my sister despises it. go shopping","category":"word order error","reason":"This sentence places words in an order that breaks the flow of the thought, making it impossible to understand the meaning."},{"choice":"I love to go shopping; but my sister despises it.","category":"semicolon misuse","reason":"A semicolon is usually used to join two sentences without a conjunction. When you use 'but', you should use a comma instead of a semicolon."},{"choice":"I love to go shopping. But my sister despises it.","category":"sentence fragment","reason":"While this is not strictly forbidden in casual writing, 'But' is a coordinating conjunction meant to link thoughts within one sentence rather than starting a new one."},""]},"studyAid":{"definition":"Use a comma before a coordinating conjunction (for, and, nor, but, or, yet, so) when it connects two complete thoughts.","example":"Correct: I was tired, but I finished my homework. Incorrect: I was tired but I finished my homework.","strategyClue":"Find the conjunction in the middle of the sentence. If there are two complete, independent sentences on either side of it, check to see if a comma separates them.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":23,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":227,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0239","version":3,"contentHash":"sha256:16a521c77e9d4d0fc9bb19b6bde3aadd4097c794dfbace66e8d91064085a48e0","question":"Which sentence is punctuated correctly to show plural possession?","choices":["My sister’s cat ran away into my neighbors yard.","My sisters cat ran away into my neighbors yard.","My sister’s cat ran away into my neighbor’s yard.","My sisters cat ran away into my neighbor’s yard."],"correct":2,"explanation":{"correct":"Answer: My sister’s cat ran away into my neighbor’s yard. To show singular possession, place the apostrophe before the 's' (sister’s cat, neighbor’s yard).","incorrect":[{"choice":"My sister’s cat ran away into my neighbors yard.","category":"missing possessive apostrophe","reason":"The word 'neighbors' is missing an apostrophe before the 's' to show that the yard belongs to the neighbor."},{"choice":"My sisters cat ran away into my neighbors yard.","category":"missing possessive apostrophes","reason":"Both 'sisters' and 'neighbors' describe ownership and require an apostrophe to show possession."},"",{"choice":"My sisters cat ran away into my neighbor’s yard.","category":"missing possessive apostrophe","reason":"The word 'sisters' is missing an apostrophe to show that the cat belongs to your sister."}]},"studyAid":{"definition":"Use an apostrophe before the 's' ('s) to show that one person or thing owns something.","example":"The dog's bowl (one dog), The teacher's desk (one teacher).","strategyClue":"Ask yourself 'who owns the item?' and place an apostrophe before the 's' of the owner's name. If the word ends in 's' but does not have an apostrophe, it is just a plural noun and not showing ownership.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":35,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":239,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0242","version":3,"contentHash":"sha256:d347e8f7ed716deca993d211eeac9c5a0e3dfff2700465d89d8b82cca52bdc7e","question":"Which sentence uses correct punctuation?","choices":["Coach yelled, Run!","Coach yelled, “Run!”","Coach yelled. “Run!”","“Coach yelled, Run!”"],"correct":1,"explanation":{"correct":"Answer: Coach yelled, “Run!”. When a speaker says something directly, you must use a comma to separate the speaker from the quote, followed by the opening quotation mark before the first word of the spoken dialogue.","incorrect":[{"choice":"Coach yelled, Run!","category":"missing quotation marks","reason":"When someone is speaking, you must use quotation marks to show exactly what they said. Without them, the sentence is missing the required dialogue punctuation."},"",{"choice":"Coach yelled. “Run!”","category":"incorrect sentence punctuation","reason":"Using a period after 'yelled' incorrectly breaks the sentence into two separate thoughts. Since 'yelled' leads directly into the speech, a comma is the correct punctuation to use."},{"choice":"“Coach yelled, Run!”","category":"misplaced quotation marks","reason":"Quotation marks should only surround the words being spoken. Putting them around the whole sentence implies that the coach was speaking the entire sentence, including their own title."}]},"studyAid":{"definition":"Direct quotations use a comma to introduce the speech and quotation marks to show exactly what was said.","example":"Mom said, “Close the door.” vs. Mom said “Close the door.” (missing comma)","strategyClue":"Identify the exact words that come out of the character's mouth and place quotation marks only around those words. Then, look for the speech tag (like 'yelled' or 'said') and ensure it is separated from the quote by a comma.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":38,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":242,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0245","version":3,"contentHash":"sha256:f0b9e044558c2f9cc0afc7ea8a74cdfa44a7f354a51ef48b920cf32e38ac84cb","question":"Which sentence is punctuated correctly?","choices":["“Is that my blue dress you have on”? my sister inquired.","“Is that my blue dress you have on?” my sister inquired.","“Is that my blue dress you have on” my sister inquired?","“Is that my blue dress you have on? my sister inquired.”"],"correct":1,"explanation":{"correct":"Answer: “Is that my blue dress you have on?” my sister inquired. In dialogue, the closing quotation mark comes immediately after the punctuation that ends the speaker's sentence, before identifying who is speaking.","incorrect":[{"choice":"“Is that my blue dress you have on”? my sister inquired.","category":"misplaced closing quotation","reason":"The question mark belongs inside the quotation marks because it is part of what the person is saying. Placing it outside incorrectly separates the question from the speaker's actual words."},"",{"choice":"“Is that my blue dress you have on” my sister inquired?","category":"missing sentence punctuation","reason":"This option is missing a question mark at the end of the spoken question. The question mark must be inside the quotation marks to show that the dialogue itself is a question."},{"choice":"“Is that my blue dress you have on? my sister inquired.”","category":"incorrect quotation boundaries","reason":"The quotation marks should only enclose the actual words spoken. By including 'my sister inquired' inside the marks, the sentence incorrectly implies the sister is saying her own name or title."}]},"studyAid":{"definition":"When writing dialogue, put the punctuation mark that ends the spoken words inside the closing quotation marks, then follow with the tag identifying the speaker.","example":"\"Hello!\" she shouted. \"Are you coming?\" he asked. \"I am tired,\" he whispered.","strategyClue":"Identify exactly which words the person is saying out loud. Place quotation marks around only those specific words and ensure the sentence-ending punctuation (like ?, !, or .) stays tucked safely inside the closing mark.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":41,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":245,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0248","version":5,"contentHash":"sha256:4a55c9c3631e9805b9cd8295a54496891caa4443f40de779a76bbaef6943ab29","question":"Which of the following would be an example of informal language?","choices":["I would really like to come by and visit with you.","I’d like to come see ya.","Would you be available tomorrow for visitors?","We your child’s can communicate about behavior during my conference period."],"correct":1,"explanation":{"correct":"Answer: I’d like to come see ya. Informal language often uses contractions like 'I'd' and slang or shortened words like 'ya' to make the tone sound more like casual conversation.","incorrect":[{"choice":"I would really like to come by and visit with you.","category":"formal sentence structure","reason":"This sentence uses complete words without contractions, making it sound more professional and polite rather than casual."},"",{"choice":"Would you be available tomorrow for visitors?","category":"professional register","reason":"This is a formal inquiry. It uses a polite, standard structure suitable for professional or serious communication."},{"choice":"We your child’s can communicate about behavior during my conference period.","category":"ungrammatical sentence","reason":"This sentence contains word order errors that make it confusing, rather than just being an example of informal language."}]},"studyAid":{"definition":"Informal language is used when talking to friends or family and often includes contractions, slang, and relaxed sentence structures.","example":"Formal: 'I do not know.' vs. Informal: 'I dunno.' / Formal: 'Hello, how are you?' vs. Informal: 'Hey, what's up?'","strategyClue":"Look for words that represent how people naturally talk in casual settings, such as shortcuts or shortened versions of words, rather than complete, structured phrases.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":44,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":248,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0251","version":4,"contentHash":"sha256:b66b488c96585ac682b9130e28edd8667e06655c2cf1d11807db9bfc8224f8e4","question":"What the would be correct punctuation to the sentence? end following What did you do during summer break","choices":[".","!",",","?"],"correct":3,"explanation":{"correct":"Answer: ?. The sentence 'What did you do during summer break' is an interrogative sentence, which means it is asking a direct question. All direct questions must end with a question mark.","incorrect":[{"choice":".","category":"period usage","reason":"A period is used for statements or commands. Since this sentence begins with the question word 'What', it is a request for information and needs a question mark instead."},{"choice":"!","category":"exclamation point usage","reason":"An exclamation point is used for strong emotions or excitement. This sentence is asking for information, so it requires a question mark rather than showing surprise."},{"choice":",","category":"incorrect punctuation mark","reason":"A comma is used to separate parts of a sentence or list items, not to end a complete thought. You must use a terminal punctuation mark like a question mark here."},""]},"studyAid":{"definition":"A question mark is used at the end of a sentence that asks a question to find out information.","example":"Where is my book? What time is lunch? How are you feeling today?","strategyClue":"Look at the first word of the sentence. If it is a question word like 'who', 'what', 'where', 'when', or 'how', consider if the sentence is asking you to provide information.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":47,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":251,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-end-sentence-q0299","version":3,"contentHash":"sha256:449d3c68086359d71f03b9a9dbb532ee830e94a0848163da974544eb5369509e","question":"What type of sentence is this? Let me tell you about my trip to France.","choices":["exclamatory","declarative","imperative","interrogative"],"correct":1,"explanation":{"correct":"Answer: declarative. A declarative sentence makes a statement or expresses an opinion, and it ends with a period. Since this sentence shares information about a trip, it is a statement.","incorrect":[{"choice":"exclamatory","category":"wrong sentence type","reason":"Exclamatory sentences express strong emotion and end with an exclamation mark, which this sentence does not have."},"",{"choice":"imperative","category":"wrong sentence type","reason":"Imperative sentences give a command or request. While this sentence starts with a verb, it is providing information rather than ordering someone to do something."},{"choice":"interrogative","category":"wrong sentence type","reason":"Interrogative sentences ask a question and end with a question mark. This sentence is telling us something instead of seeking information."}]},"studyAid":{"definition":"A declarative sentence is a simple statement that gives information and ends with a period.","example":"I like pizza. (Declarative) vs. Do you like pizza? (Interrogative) vs. Eat your pizza! (Imperative)","strategyClue":"Look at the punctuation mark at the end and decide if the sentence is sharing a fact, asking a question, giving a command, or showing strong excitement.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-end-sentence","sourceFile":"Language Usage_Basic 2_4th grade.pdf","sourceQuestionNumber":44,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":299,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
